--
-- Table structure for table `bbf_incapacidades`
--

DROP TABLE IF EXISTS `bbf_incapacidades`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bbf_incapacidades` (
  `ID_INCAPACIDAD` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_NOVEDAD` bigint(20) NOT NULL,
  `ID_EPS` int(11) DEFAULT NULL,
  `NUMERO_CERTIFICADO` varchar(100) DEFAULT NULL,
  `NUMERO_RADICADO` varchar(100) DEFAULT NULL,
  `DIAGNOSTICO` varchar(500) DEFAULT NULL,
  `CODIGO_CIE10` varchar(20) DEFAULT NULL,
  `ORIGEN_INCAPACIDAD` enum('ENFERMEDAD_GENERAL','ACCIDENTE_LABORAL','ENFERMEDAD_LABORAL','ACCIDENTE_TRANSITO','LICENCIA_MATERNIDAD','LICENCIA_PATERNIDAD','OTRO') NOT NULL DEFAULT 'ENFERMEDAD_GENERAL',
  `ENTIDAD_EMISORA` varchar(200) DEFAULT NULL,
  `ES_PRORROGA` tinyint(1) NOT NULL DEFAULT 0,
  `ID_INCAPACIDAD_ORIGEN` bigint(20) DEFAULT NULL,
  `FECHA_RADICACION` date DEFAULT NULL,
  `OBSERVACIONES_MEDICAS` text DEFAULT NULL,
  `CREATED_AT` datetime NOT NULL DEFAULT current_timestamp(),
  `UPDATED_AT` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`ID_INCAPACIDAD`),
  UNIQUE KEY `UQ_BBF_INCAPACIDAD_NOVEDAD` (`ID_NOVEDAD`),
  KEY `IDX_BBF_INCAPACIDAD_EPS` (`ID_EPS`),
  KEY `IDX_BBF_INCAPACIDAD_CERTIFICADO` (`NUMERO_CERTIFICADO`),
  KEY `FK_BBF_INCAPACIDAD_ORIGEN` (`ID_INCAPACIDAD_ORIGEN`),
  CONSTRAINT `FK_BBF_INCAPACIDAD_EPS` FOREIGN KEY (`ID_EPS`) REFERENCES `bbf_entidades_seguridad_social` (`ID_ENTIDAD_SEGURIDAD_SOCIAL`),
  CONSTRAINT `FK_BBF_INCAPACIDAD_NOVEDAD` FOREIGN KEY (`ID_NOVEDAD`) REFERENCES `bbf_novedades_empleado` (`ID_NOVEDAD`),
  CONSTRAINT `FK_BBF_INCAPACIDAD_ORIGEN` FOREIGN KEY (`ID_INCAPACIDAD_ORIGEN`) REFERENCES `bbf_incapacidades` (`ID_INCAPACIDAD`),
  CONSTRAINT `CK_BBF_INCAPACIDAD_PRORROGA` CHECK (`ES_PRORROGA` = 0 or `ID_INCAPACIDAD_ORIGEN` is not null)
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

