DROP TABLE IF EXISTS `bbf_novedad_historial`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bbf_novedad_historial` (
  `ID_NOVEDAD_HISTORIAL` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_NOVEDAD` bigint(20) NOT NULL,
  `ACCION` enum('CREACION','ACTUALIZACION','CAMBIO_ESTADO','EVIDENCIA_AGREGADA','ANULACION') NOT NULL,
  `ESTADO_ANTERIOR` varchar(30) DEFAULT NULL,
  `ESTADO_NUEVO` varchar(30) DEFAULT NULL,
  `DETALLE` text DEFAULT NULL,
  `ID_USUARIO` int(11) NOT NULL,
  `CREATED_AT` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`ID_NOVEDAD_HISTORIAL`),
  KEY `IDX_BBF_NOVEDAD_HISTORIAL_NOVEDAD` (`ID_NOVEDAD`,`CREATED_AT`),
  KEY `FK_BBF_NOVEDAD_HISTORIAL_USUARIO` (`ID_USUARIO`),
  CONSTRAINT `FK_BBF_NOVEDAD_HISTORIAL_NOVEDAD` FOREIGN KEY (`ID_NOVEDAD`) REFERENCES `bbf_novedades_empleado` (`ID_NOVEDAD`),
  CONSTRAINT `FK_BBF_NOVEDAD_HISTORIAL_USUARIO` FOREIGN KEY (`ID_USUARIO`) REFERENCES `bbf_usuarios` (`ID_USUARIO`)
) ENGINE=InnoDB AUTO_INCREMENT=363 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

