--
-- Table structure for table `bbf_novedades_empleado`
--

DROP TABLE IF EXISTS `bbf_novedades_empleado`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bbf_novedades_empleado` (
  `ID_NOVEDAD` bigint(20) NOT NULL AUTO_INCREMENT,
  `ID_EMPLEADO` int(11) NOT NULL,
  `ID_TIPO_NOVEDAD` int(11) NOT NULL,
  `FECHA_INICIO` date NOT NULL,
  `FECHA_FIN` date DEFAULT NULL,
  `NUMERO_DIAS` int(11) NOT NULL DEFAULT 1,
  `MOTIVO` varchar(500) DEFAULT NULL,
  `OBSERVACIONES` text DEFAULT NULL,
  `ESTADO` enum('REGISTRADA','VALIDADA','CERRADA','ANULADA') NOT NULL DEFAULT 'REGISTRADA',
  `ID_REGISTRADO_POR` int(11) NOT NULL,
  `ID_ULTIMA_MODIFICACION_POR` int(11) DEFAULT NULL,
  `ID_ANULADO_POR` int(11) DEFAULT NULL,
  `FECHA_ANULACION` datetime DEFAULT NULL,
  `MOTIVO_ANULACION` varchar(500) DEFAULT NULL,
  `CREATED_AT` datetime NOT NULL DEFAULT current_timestamp(),
  `UPDATED_AT` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`ID_NOVEDAD`),
  KEY `IDX_BBF_NOVEDAD_EMPLEADO_FECHA` (`ID_EMPLEADO`,`FECHA_INICIO`,`FECHA_FIN`),
  KEY `IDX_BBF_NOVEDAD_TIPO_ESTADO` (`ID_TIPO_NOVEDAD`,`ESTADO`),
  KEY `IDX_BBF_NOVEDAD_ESTADO_FECHA` (`ESTADO`,`FECHA_INICIO`),
  KEY `FK_BBF_NOVEDAD_REGISTRADO` (`ID_REGISTRADO_POR`),
  KEY `FK_BBF_NOVEDAD_MODIFICADO` (`ID_ULTIMA_MODIFICACION_POR`),
  KEY `FK_BBF_NOVEDAD_ANULADO` (`ID_ANULADO_POR`),
  CONSTRAINT `FK_BBF_NOVEDAD_ANULADO` FOREIGN KEY (`ID_ANULADO_POR`) REFERENCES `bbf_usuarios` (`ID_USUARIO`),
  CONSTRAINT `FK_BBF_NOVEDAD_EMPLEADO` FOREIGN KEY (`ID_EMPLEADO`) REFERENCES `bbf_empleados` (`ID_EMPLEADO`),
  CONSTRAINT `FK_BBF_NOVEDAD_MODIFICADO` FOREIGN KEY (`ID_ULTIMA_MODIFICACION_POR`) REFERENCES `bbf_usuarios` (`ID_USUARIO`),
  CONSTRAINT `FK_BBF_NOVEDAD_REGISTRADO` FOREIGN KEY (`ID_REGISTRADO_POR`) REFERENCES `bbf_usuarios` (`ID_USUARIO`),
  CONSTRAINT `FK_BBF_NOVEDAD_TIPO` FOREIGN KEY (`ID_TIPO_NOVEDAD`) REFERENCES `bbf_tipos_novedad` (`ID_TIPO_NOVEDAD`),
  CONSTRAINT `CK_BBF_NOVEDAD_FECHAS` CHECK (`FECHA_FIN` is null or `FECHA_FIN` >= `FECHA_INICIO`),
  CONSTRAINT `CK_BBF_NOVEDAD_DIAS` CHECK (`NUMERO_DIAS` > 0)
) ENGINE=InnoDB AUTO_INCREMENT=90 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

