CREATE  PROCEDURE `SP_BBF_CARGOS_LISTAR`(
    IN P_SOLO_ACTIVOS TINYINT
)
BEGIN
    SELECT
        ID_CARGO,
        NOMBRE,
        DESCRIPCION,
        ACTIVO,
        CREATED_AT,
        UPDATED_AT
    FROM bbf_cargos
    WHERE P_SOLO_ACTIVOS = 0 OR ACTIVO = 1
    ORDER BY NOMBRE ASC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
