/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_CONTRATACION_LUGAR_EXPEDICION_GUARDAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_CONTRATACION_LUGAR_EXPEDICION_GUARDAR`(
 IN P_ID_EMPLEADO INT, IN P_LUGAR_EXPEDICION_DOCUMENTO VARCHAR(150))
BEGIN
 IF NOT EXISTS(SELECT 1 FROM bbf_empleados WHERE ID_EMPLEADO=P_ID_EMPLEADO AND IFNULL(ELIMINADO,0)=0) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El empleado no existe o fue eliminado.';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM bbf_empleado_ficha_ingreso WHERE ID_EMPLEADO=P_ID_EMPLEADO AND IFNULL(ELIMINADO,0)=0) THEN
  INSERT INTO bbf_empleado_ficha_ingreso(ID_EMPLEADO,LUGAR_EXPEDICION_DOCUMENTO,ESTADO_FICHA)
  VALUES(P_ID_EMPLEADO,NULLIF(TRIM(P_LUGAR_EXPEDICION_DOCUMENTO),''),'INCOMPLETA');
 ELSE
  UPDATE bbf_empleado_ficha_ingreso
  SET LUGAR_EXPEDICION_DOCUMENTO=NULLIF(TRIM(P_LUGAR_EXPEDICION_DOCUMENTO),''),UPDATED_AT=CURRENT_TIMESTAMP
  WHERE ID_EMPLEADO=P_ID_EMPLEADO AND IFNULL(ELIMINADO,0)=0;
 END IF;
 SELECT ID_FICHA_INGRESO,ID_EMPLEADO,LUGAR_EXPEDICION_DOCUMENTO
 FROM bbf_empleado_ficha_ingreso WHERE ID_EMPLEADO=P_ID_EMPLEADO AND IFNULL(ELIMINADO,0)=0 LIMIT 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_CONTRATACION_LUGAR_EXPEDICION_OBTENER` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_CONTRATACION_LUGAR_EXPEDICION_OBTENER`(IN P_ID_EMPLEADO INT)
BEGIN
 SELECT LUGAR_EXPEDICION_DOCUMENTO FROM bbf_empleado_ficha_ingreso
 WHERE ID_EMPLEADO=P_ID_EMPLEADO AND IFNULL(ELIMINADO,0)=0 LIMIT 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
