CREATE  PROCEDURE `SP_BBF_DEPARTAMENTOS_LISTAR`()
BEGIN
    SELECT
        ID_DEPARTAMENTO,
        CODIGO_DANE,
        NOMBRE
    FROM bbf_departamentos
    WHERE ACTIVO = 1
    ORDER BY NOMBRE;
