CREATE  PROCEDURE `SP_BBF_DOMINIOS_LISTAR`(
    IN P_SOLO_ACTIVOS TINYINT
)
BEGIN
    SELECT
        ID_DOMINIO,
        DOMINIO,
        DESCRIPCION,
        ACTIVO,
        CREATED_AT,
        UPDATED_AT
    FROM bbf_dominios_autorizados
    WHERE P_SOLO_ACTIVOS = 0 OR ACTIVO = 1
    ORDER BY DOMINIO ASC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
