CREATE  PROCEDURE `SP_BBF_DOTACION_COMBINACIONES_LISTAR`()
BEGIN

    SELECT
        C.ID_DOTACION_COMBINACION,

        C.CODIGO,

        C.NOMBRE,

        C.DESCRIPCION,

        C.ACTIVO

    FROM bbf_dotacion_combinaciones C

    WHERE C.ACTIVO = 1

    ORDER BY
        C.ID_DOTACION_COMBINACION ASC;

END ;;
DELIMITER ;
