CREATE  PROCEDURE `SP_BBF_DOTACION_TIPOS_LISTAR`(
    IN P_SOLO_ACTIVOS TINYINT
)
BEGIN
    SELECT
        ID_TIPO_DOTACION,
        NOMBRE,
        DESCRIPCION,
        REQUIERE_TALLA,
        ACTIVO,
        CREATED_AT,
        UPDATED_AT
    FROM bbf_tipos_dotacion
    WHERE P_SOLO_ACTIVOS = 0 OR ACTIVO = 1
    ORDER BY NOMBRE ASC;
END ;;
