CREATE  PROCEDURE `SP_BBF_HERRAMIENTAS_ENTREGA_EVIDENCIAS_LISTAR`(
    IN p_id_entrega INT
)
BEGIN
    SELECT
        EV.id_evidencia,
        EV.id_entrega,
        EV.nombre_archivo,
        EV.nombre_original,
        EV.archivo_url,
