CREATE  PROCEDURE `SP_BBF_HERRAMIENTAS_ENTREGA_OBTENER`(
    in p_id_entrega int
)
begin

    select
        en.id_entrega,
        en.id_empleado,

        e.numero_documento,
        e.nombres,
        e.apellidos,

        concat(
            e.nombres,
            ' ',
            e.apellidos
        ) as empleado,

        en.fecha_entrega,
        en.estado,
        en.observaciones,
        en.fecha_confirmacion,
        en.created_at,
        en.updated_at

    from bbf_herramientas_entregas en

    inner join bbf_empleados e
        on e.id_empleado = en.id_empleado

    where en.id_entrega = p_id_entrega;

end ;;
DELIMITER ;
