CREATE  PROCEDURE `SP_BBF_HERRAMIENTAS_LISTAR`(
    in p_solo_activos tinyint
)
begin

    select
        h.id_herramienta,
        h.nombre,
        h.descripcion,
        h.activo,
        h.created_at,
        h.updated_at
    from bbf_herramientas h
    where
        p_solo_activos = 0
        or h.activo = 1
    order by h.nombre asc;

end ;;
