DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_INCAPACIDADES_SEGUIMIENTO_LISTAR`(
    IN P_ID_EMPLEADO INT,
    IN P_ID_ENTIDAD_RESPONSABLE INT,
    IN P_ESTADO_SEGUIMIENTO VARCHAR(30),
    IN P_FECHA_DESDE DATE,
    IN P_FECHA_HASTA DATE
)
BEGIN
    SELECT
        N.`ID_NOVEDAD`,
        I.`ID_INCAPACIDAD`,
        E.`ID_EMPLEADO`,
        TD.`NOMBRE` AS `TIPO_DOCUMENTO`,
        E.`NUMERO_DOCUMENTO`,
        CONCAT_WS(' ',E.`APELLIDOS`,E.`NOMBRES`) AS `APELLIDO_Y_NOMBRE_COMPLETO`,
        I.`DIAGNOSTICO`,
        I.`CODIGO_CIE10`,
        N.`FECHA_INICIO`,
        N.`FECHA_FIN`,
        N.`NUMERO_DIAS` AS `DIAS_INCAPACIDAD`,
        S.`DIAS_PAGADOS_EMPRESA`,
        S.`DIAS_PAGAR_ENTIDAD`,
        I.`NUMERO_CERTIFICADO` AS `NUMERO_INCAPACIDAD`,
        S.`ESTADO_TRANSCRIPCION`,
        S.`CANAL_TRANSCRIPCION`,
        S.`FECHA_TRANSCRIPCION`,
        I.`NUMERO_RADICADO`,
        I.`FECHA_RADICACION`,
        S.`ESTADO_SOLICITUD_PAGO`,
        S.`FECHA_SOLICITUD_PAGO`,
        S.`VALOR_INCAPACIDAD`,
        S.`VALOR_RECIBIDO_ENTIDAD`,
        S.`VALOR_PAGADO_EMPRESA_TRABAJADOR`,
        S.`VALOR_ADEUDADO_ENTIDAD`,
        S.`VALOR_PAGADO_TRABAJADOR`,
        S.`FECHA_ULTIMO_PAGO`,
        ES.`NOMBRE` AS `ENTIDAD_RESPONSABLE`,
        ES.`TIPO_ENTIDAD`,
        E.`ESTADO_EMPLEADO` AS `ESTADO_TRABAJADOR`,
        S.`ESTADO_SEGUIMIENTO`,
        COALESCE(S.`OBSERVACIONES_SEGUIMIENTO`,N.`OBSERVACIONES`) AS `OBSERVACIONES`,
        N.`CREATED_AT`,
        S.`UPDATED_AT`
    FROM `bbf_incapacidades` I
    INNER JOIN `bbf_novedades_empleado` N
        ON N.`ID_NOVEDAD` = I.`ID_NOVEDAD`
    INNER JOIN `bbf_empleados` E
        ON E.`ID_EMPLEADO` = N.`ID_EMPLEADO`
    LEFT JOIN `bbf_tipos_documento` TD
        ON TD.`ID_TIPO_DOCUMENTO` = E.`ID_TIPO_DOCUMENTO`
    INNER JOIN `bbf_incapacidad_seguimiento` S
        ON S.`ID_INCAPACIDAD` = I.`ID_INCAPACIDAD`
    LEFT JOIN `bbf_entidades_seguridad_social` ES
        ON ES.`ID_ENTIDAD_SEGURIDAD_SOCIAL` = S.`ID_ENTIDAD_RESPONSABLE`
    WHERE (P_ID_EMPLEADO IS NULL OR P_ID_EMPLEADO = 0 OR E.`ID_EMPLEADO` = P_ID_EMPLEADO)
      AND (P_ID_ENTIDAD_RESPONSABLE IS NULL OR P_ID_ENTIDAD_RESPONSABLE = 0
           OR S.`ID_ENTIDAD_RESPONSABLE` = P_ID_ENTIDAD_RESPONSABLE)
      AND (P_ESTADO_SEGUIMIENTO IS NULL OR TRIM(P_ESTADO_SEGUIMIENTO) = ''
           OR S.`ESTADO_SEGUIMIENTO` = UPPER(TRIM(P_ESTADO_SEGUIMIENTO)))
      AND (P_FECHA_DESDE IS NULL OR N.`FECHA_FIN` >= P_FECHA_DESDE)
      AND (P_FECHA_HASTA IS NULL OR N.`FECHA_INICIO` <= P_FECHA_HASTA)
    ORDER BY N.`FECHA_INICIO` DESC,N.`ID_NOVEDAD` DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_INCAPACIDAD_ACTUALIZAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_INCAPACIDAD_ACTUALIZAR`(
    IN P_ID_NOVEDAD BIGINT,
    IN P_FECHA_INICIO DATE,
    IN P_FECHA_FIN DATE,
    IN P_DIAGNOSTICO VARCHAR(500),
    IN P_CODIGO_CIE10 VARCHAR(20),
    IN P_ID_EPS INT,
    IN P_ORIGEN_INCAPACIDAD VARCHAR(40),
    IN P_NUMERO_CERTIFICADO VARCHAR(100),
    IN P_NUMERO_RADICADO VARCHAR(100),
    IN P_ENTIDAD_EMISORA VARCHAR(200),
    IN P_ES_PRORROGA TINYINT,
    IN P_ID_INCAPACIDAD_ORIGEN BIGINT,
    IN P_FECHA_RADICACION DATE,
    IN P_OBSERVACIONES TEXT,
    IN P_ID_USUARIO INT
)
BEGIN
    DECLARE V_ESTADO VARCHAR(30);
    DECLARE V_DIAS INT;
    DECLARE V_ORIGEN VARCHAR(40);

    SELECT N.ESTADO INTO V_ESTADO
    FROM bbf_novedades_empleado N
    INNER JOIN bbf_incapacidades I ON I.ID_NOVEDAD=N.ID_NOVEDAD
    WHERE N.ID_NOVEDAD=P_ID_NOVEDAD LIMIT 1;
    IF V_ESTADO IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La incapacidad no existe.';
    END IF;
    IF V_ESTADO IN ('CERRADA','ANULADA') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No se puede editar una incapacidad cerrada o anulada.';
    END IF;
    IF P_FECHA_INICIO IS NULL OR P_FECHA_FIN IS NULL OR P_FECHA_FIN<P_FECHA_INICIO THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El rango de fechas no es valido.';
    END IF;
    IF P_ID_EPS IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM bbf_entidades_seguridad_social
        WHERE ID_ENTIDAD_SEGURIDAD_SOCIAL=P_ID_EPS AND TIPO_ENTIDAD='EPS' AND ACTIVO=1
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La EPS no es valida.';
    END IF;
    IF IFNULL(P_ES_PRORROGA,0)=1 AND (P_ID_INCAPACIDAD_ORIGEN IS NULL OR NOT EXISTS (
        SELECT 1 FROM bbf_incapacidades WHERE ID_INCAPACIDAD=P_ID_INCAPACIDAD_ORIGEN
    )) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La prorroga requiere una incapacidad de origen valida.';
    END IF;
    SET V_ORIGEN=UPPER(TRIM(IFNULL(P_ORIGEN_INCAPACIDAD,'ENFERMEDAD_GENERAL')));
    IF V_ORIGEN NOT IN ('ENFERMEDAD_GENERAL','ACCIDENTE_LABORAL','ENFERMEDAD_LABORAL','ACCIDENTE_TRANSITO','LICENCIA_MATERNIDAD','LICENCIA_PATERNIDAD','OTRO') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El origen de incapacidad no es valido.';
    END IF;

    SET V_DIAS=DATEDIFF(P_FECHA_FIN,P_FECHA_INICIO)+1;
    START TRANSACTION;
    UPDATE bbf_novedades_empleado SET
        FECHA_INICIO=P_FECHA_INICIO, FECHA_FIN=P_FECHA_FIN, NUMERO_DIAS=V_DIAS,
        MOTIVO=NULLIF(TRIM(P_DIAGNOSTICO),''), OBSERVACIONES=NULLIF(TRIM(P_OBSERVACIONES),''),
        ID_ULTIMA_MODIFICACION_POR=P_ID_USUARIO, UPDATED_AT=CURRENT_TIMESTAMP
    WHERE ID_NOVEDAD=P_ID_NOVEDAD;

    UPDATE bbf_incapacidades SET
        ID_EPS=P_ID_EPS, NUMERO_CERTIFICADO=NULLIF(TRIM(P_NUMERO_CERTIFICADO),''),
        NUMERO_RADICADO=NULLIF(TRIM(P_NUMERO_RADICADO),''), DIAGNOSTICO=NULLIF(TRIM(P_DIAGNOSTICO),''),
        CODIGO_CIE10=NULLIF(UPPER(TRIM(P_CODIGO_CIE10)),''), ORIGEN_INCAPACIDAD=V_ORIGEN,
        ENTIDAD_EMISORA=NULLIF(TRIM(P_ENTIDAD_EMISORA),''), ES_PRORROGA=IFNULL(P_ES_PRORROGA,0),
        ID_INCAPACIDAD_ORIGEN=P_ID_INCAPACIDAD_ORIGEN, FECHA_RADICACION=P_FECHA_RADICACION,
        OBSERVACIONES_MEDICAS=NULLIF(TRIM(P_OBSERVACIONES),''), UPDATED_AT=CURRENT_TIMESTAMP
    WHERE ID_NOVEDAD=P_ID_NOVEDAD;

    INSERT INTO bbf_novedad_historial
    (ID_NOVEDAD,ACCION,ESTADO_ANTERIOR,ESTADO_NUEVO,DETALLE,ID_USUARIO)
    VALUES (P_ID_NOVEDAD,'ACTUALIZACION',V_ESTADO,V_ESTADO,'Datos de incapacidad actualizados.',P_ID_USUARIO);
    COMMIT;
    SELECT P_ID_NOVEDAD AS ID_NOVEDAD, V_DIAS AS NUMERO_DIAS;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_INCAPACIDAD_CREAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_INCAPACIDAD_CREAR`(
    IN P_ID_EMPLEADO INT,
    IN P_FECHA_INICIO DATE,
    IN P_FECHA_FIN DATE,
    IN P_DIAGNOSTICO VARCHAR(500),
    IN P_CODIGO_CIE10 VARCHAR(20),
    IN P_ID_EPS INT,
    IN P_ORIGEN_INCAPACIDAD VARCHAR(40),
    IN P_NUMERO_CERTIFICADO VARCHAR(100),
    IN P_NUMERO_RADICADO VARCHAR(100),
    IN P_ENTIDAD_EMISORA VARCHAR(200),
    IN P_ES_PRORROGA TINYINT,
    IN P_ID_INCAPACIDAD_ORIGEN BIGINT,
    IN P_FECHA_RADICACION DATE,
    IN P_OBSERVACIONES TEXT,
    IN P_ID_USUARIO INT
)
BEGIN
    DECLARE V_ID_TIPO INT;
    DECLARE V_ID_NOVEDAD BIGINT;
    DECLARE V_ID_INCAPACIDAD BIGINT;
    DECLARE V_DIAS INT;
    DECLARE V_ORIGEN VARCHAR(40);

    IF NOT EXISTS (SELECT 1 FROM bbf_empleados WHERE ID_EMPLEADO=P_ID_EMPLEADO AND IFNULL(ELIMINADO,0)=0) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El empleado no existe o fue eliminado.';
    END IF;
    IF P_FECHA_INICIO IS NULL OR P_FECHA_FIN IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Las fechas de inicio y finalizacion son obligatorias.';
    END IF;
    IF P_FECHA_FIN < P_FECHA_INICIO THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La fecha final no puede ser anterior a la fecha inicial.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM bbf_usuarios WHERE ID_USUARIO=P_ID_USUARIO) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El usuario registrador no existe.';
    END IF;
    IF P_ID_EPS IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM bbf_entidades_seguridad_social
        WHERE ID_ENTIDAD_SEGURIDAD_SOCIAL=P_ID_EPS AND TIPO_ENTIDAD='EPS' AND ACTIVO=1
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La EPS no existe, esta inactiva o no corresponde a una EPS.';
    END IF;
    IF IFNULL(P_ES_PRORROGA,0)=1 AND (P_ID_INCAPACIDAD_ORIGEN IS NULL OR NOT EXISTS (
        SELECT 1 FROM bbf_incapacidades WHERE ID_INCAPACIDAD=P_ID_INCAPACIDAD_ORIGEN
    )) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La prorroga requiere una incapacidad de origen valida.';
    END IF;

    SET V_ORIGEN=UPPER(TRIM(IFNULL(P_ORIGEN_INCAPACIDAD,'ENFERMEDAD_GENERAL')));
    IF V_ORIGEN NOT IN ('ENFERMEDAD_GENERAL','ACCIDENTE_LABORAL','ENFERMEDAD_LABORAL','ACCIDENTE_TRANSITO','LICENCIA_MATERNIDAD','LICENCIA_PATERNIDAD','OTRO') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El origen de incapacidad no es valido.';
    END IF;

    SELECT ID_TIPO_NOVEDAD INTO V_ID_TIPO
    FROM bbf_tipos_novedad WHERE CODIGO='INCAPACIDAD' AND ACTIVO=1 LIMIT 1;
    IF V_ID_TIPO IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El tipo INCAPACIDAD no esta disponible.';
    END IF;

    SET V_DIAS=DATEDIFF(P_FECHA_FIN,P_FECHA_INICIO)+1;
    START TRANSACTION;
    INSERT INTO bbf_novedades_empleado
    (ID_EMPLEADO,ID_TIPO_NOVEDAD,FECHA_INICIO,FECHA_FIN,NUMERO_DIAS,MOTIVO,OBSERVACIONES,ID_REGISTRADO_POR)
    VALUES
    (P_ID_EMPLEADO,V_ID_TIPO,P_FECHA_INICIO,P_FECHA_FIN,V_DIAS,NULLIF(TRIM(P_DIAGNOSTICO),''),NULLIF(TRIM(P_OBSERVACIONES),''),P_ID_USUARIO);
    SET V_ID_NOVEDAD=LAST_INSERT_ID();

    INSERT INTO bbf_incapacidades
    (ID_NOVEDAD,ID_EPS,NUMERO_CERTIFICADO,NUMERO_RADICADO,DIAGNOSTICO,CODIGO_CIE10,
     ORIGEN_INCAPACIDAD,ENTIDAD_EMISORA,ES_PRORROGA,ID_INCAPACIDAD_ORIGEN,FECHA_RADICACION,OBSERVACIONES_MEDICAS)
    VALUES
    (V_ID_NOVEDAD,P_ID_EPS,NULLIF(TRIM(P_NUMERO_CERTIFICADO),''),NULLIF(TRIM(P_NUMERO_RADICADO),''),
     NULLIF(TRIM(P_DIAGNOSTICO),''),NULLIF(UPPER(TRIM(P_CODIGO_CIE10)),''),V_ORIGEN,
     NULLIF(TRIM(P_ENTIDAD_EMISORA),''),IFNULL(P_ES_PRORROGA,0),P_ID_INCAPACIDAD_ORIGEN,
     P_FECHA_RADICACION,NULLIF(TRIM(P_OBSERVACIONES),''));
    SET V_ID_INCAPACIDAD=LAST_INSERT_ID();

    INSERT INTO bbf_novedad_historial
    (ID_NOVEDAD,ACCION,ESTADO_NUEVO,DETALLE,ID_USUARIO)
    VALUES (V_ID_NOVEDAD,'CREACION','REGISTRADA','Incapacidad registrada.',P_ID_USUARIO);
    COMMIT;

    SELECT V_ID_NOVEDAD AS ID_NOVEDAD, V_ID_INCAPACIDAD AS ID_INCAPACIDAD, V_DIAS AS NUMERO_DIAS;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_INCAPACIDAD_SEGUIMIENTO_GUARDAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_INCAPACIDAD_SEGUIMIENTO_GUARDAR`(
    IN P_ID_NOVEDAD BIGINT,
    IN P_ID_ENTIDAD_RESPONSABLE INT,
    IN P_DIAS_PAGADOS_EMPRESA INT,
    IN P_DIAS_PAGAR_ENTIDAD INT,
    IN P_ESTADO_TRANSCRIPCION VARCHAR(30),
    IN P_CANAL_TRANSCRIPCION VARCHAR(30),
    IN P_FECHA_TRANSCRIPCION DATE,
    IN P_ESTADO_SOLICITUD_PAGO VARCHAR(30),
    IN P_FECHA_SOLICITUD_PAGO DATE,
    IN P_VALOR_INCAPACIDAD DECIMAL(15,2),
    IN P_VALOR_RECIBIDO_ENTIDAD DECIMAL(15,2),
    IN P_VALOR_PAGADO_EMPRESA_TRABAJADOR DECIMAL(15,2),
    IN P_VALOR_PAGADO_TRABAJADOR DECIMAL(15,2),
    IN P_FECHA_ULTIMO_PAGO DATE,
    IN P_ESTADO_SEGUIMIENTO VARCHAR(30),
    IN P_OBSERVACIONES_SEGUIMIENTO TEXT,
    IN P_ID_USUARIO INT
)
BEGIN
    DECLARE V_ID_INCAPACIDAD BIGINT DEFAULT NULL;
    DECLARE V_TOTAL_DIAS INT DEFAULT 0;
    DECLARE V_ESTADO_NOVEDAD VARCHAR(30) DEFAULT NULL;
    DECLARE V_TRANSCRIPCION VARCHAR(30);
    DECLARE V_CANAL VARCHAR(30);
    DECLARE V_SOLICITUD VARCHAR(30);
    DECLARE V_SEGUIMIENTO VARCHAR(30);

    SELECT I.`ID_INCAPACIDAD`,N.`NUMERO_DIAS`,N.`ESTADO`
      INTO V_ID_INCAPACIDAD,V_TOTAL_DIAS,V_ESTADO_NOVEDAD
    FROM `bbf_incapacidades` I
    INNER JOIN `bbf_novedades_empleado` N
        ON N.`ID_NOVEDAD` = I.`ID_NOVEDAD`
    WHERE I.`ID_NOVEDAD` = P_ID_NOVEDAD
    LIMIT 1;

    IF V_ID_INCAPACIDAD IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La incapacidad no existe.';
    END IF;

    IF V_ESTADO_NOVEDAD = 'ANULADA' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'No se puede actualizar una incapacidad anulada.';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM `bbf_usuarios`
        WHERE `ID_USUARIO` = P_ID_USUARIO
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El usuario que realiza la actualización no existe.';
    END IF;

    IF P_ID_ENTIDAD_RESPONSABLE IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM `bbf_entidades_seguridad_social`
        WHERE `ID_ENTIDAD_SEGURIDAD_SOCIAL` = P_ID_ENTIDAD_RESPONSABLE
          AND `ACTIVO` = 1
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La entidad responsable no existe o está inactiva.';
    END IF;

    IF IFNULL(P_DIAS_PAGADOS_EMPRESA,0) < 0
       OR IFNULL(P_DIAS_PAGAR_ENTIDAD,0) < 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Los días a cargo de la empresa o entidad no pueden ser negativos.';
    END IF;

    IF IFNULL(P_DIAS_PAGADOS_EMPRESA,0)
       + IFNULL(P_DIAS_PAGAR_ENTIDAD,0) <> V_TOTAL_DIAS THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La distribución de días debe coincidir con el total de días de incapacidad.';
    END IF;

    IF IFNULL(P_VALOR_INCAPACIDAD,0) < 0
       OR IFNULL(P_VALOR_RECIBIDO_ENTIDAD,0) < 0
       OR IFNULL(P_VALOR_PAGADO_EMPRESA_TRABAJADOR,0) < 0
       OR IFNULL(P_VALOR_PAGADO_TRABAJADOR,0) < 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Los valores económicos no pueden ser negativos.';
    END IF;

    SET V_TRANSCRIPCION = UPPER(TRIM(IFNULL(P_ESTADO_TRANSCRIPCION,'PENDIENTE')));
    SET V_CANAL = NULLIF(UPPER(TRIM(P_CANAL_TRANSCRIPCION)),'');
    SET V_SOLICITUD = UPPER(TRIM(IFNULL(P_ESTADO_SOLICITUD_PAGO,'PENDIENTE')));
    SET V_SEGUIMIENTO = UPPER(TRIM(IFNULL(P_ESTADO_SEGUIMIENTO,'PENDIENTE')));

    IF V_TRANSCRIPCION NOT IN ('NO_REQUIERE','PENDIENTE','TRANSCRITA','RECHAZADA') THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El estado de transcripción no es válido.';
    END IF;

    IF V_CANAL IS NOT NULL
       AND V_CANAL NOT IN ('PLATAFORMA','CORREO','PRESENCIAL','OTRO') THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El canal de transcripción no es válido.';
    END IF;

    IF V_TRANSCRIPCION = 'TRANSCRITA' AND P_FECHA_TRANSCRIPCION IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La fecha de transcripción es obligatoria cuando está transcrita.';
    END IF;

    IF V_SOLICITUD NOT IN (
        'NO_REQUIERE','PENDIENTE','RADICADA','EN_ESTUDIO',
        'APROBADA','RECHAZADA','PAGADA_PARCIAL','PAGADA'
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El estado de solicitud de pago no es válido.';
    END IF;

    IF V_SOLICITUD IN ('RADICADA','EN_ESTUDIO','APROBADA','RECHAZADA','PAGADA_PARCIAL','PAGADA')
       AND P_FECHA_SOLICITUD_PAGO IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La fecha de solicitud es obligatoria para el estado indicado.';
    END IF;

    IF V_SEGUIMIENTO NOT IN ('PENDIENTE','EN_TRAMITE','CERRADO','CANCELADO') THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El estado de seguimiento no es válido.';
    END IF;

    INSERT INTO `bbf_incapacidad_seguimiento`
    (
        `ID_INCAPACIDAD`,
        `ID_ENTIDAD_RESPONSABLE`,
        `DIAS_PAGADOS_EMPRESA`,
        `DIAS_PAGAR_ENTIDAD`,
        `ESTADO_TRANSCRIPCION`,
        `CANAL_TRANSCRIPCION`,
        `FECHA_TRANSCRIPCION`,
        `ESTADO_SOLICITUD_PAGO`,
        `FECHA_SOLICITUD_PAGO`,
        `VALOR_INCAPACIDAD`,
        `VALOR_RECIBIDO_ENTIDAD`,
        `VALOR_PAGADO_EMPRESA_TRABAJADOR`,
        `VALOR_PAGADO_TRABAJADOR`,
        `FECHA_ULTIMO_PAGO`,
        `ESTADO_SEGUIMIENTO`,
        `OBSERVACIONES_SEGUIMIENTO`,
        `ID_REGISTRADO_POR`,
        `ID_ULTIMA_MODIFICACION_POR`
    )
    VALUES
    (
        V_ID_INCAPACIDAD,
        P_ID_ENTIDAD_RESPONSABLE,
        IFNULL(P_DIAS_PAGADOS_EMPRESA,0),
        IFNULL(P_DIAS_PAGAR_ENTIDAD,0),
        V_TRANSCRIPCION,
        V_CANAL,
        P_FECHA_TRANSCRIPCION,
        V_SOLICITUD,
        P_FECHA_SOLICITUD_PAGO,
        IFNULL(P_VALOR_INCAPACIDAD,0),
        IFNULL(P_VALOR_RECIBIDO_ENTIDAD,0),
        IFNULL(P_VALOR_PAGADO_EMPRESA_TRABAJADOR,0),
        IFNULL(P_VALOR_PAGADO_TRABAJADOR,0),
        P_FECHA_ULTIMO_PAGO,
        V_SEGUIMIENTO,
        NULLIF(TRIM(P_OBSERVACIONES_SEGUIMIENTO),''),
        P_ID_USUARIO,
        P_ID_USUARIO
    )
    ON DUPLICATE KEY UPDATE
        `ID_ENTIDAD_RESPONSABLE` = VALUES(`ID_ENTIDAD_RESPONSABLE`),
        `DIAS_PAGADOS_EMPRESA` = VALUES(`DIAS_PAGADOS_EMPRESA`),
        `DIAS_PAGAR_ENTIDAD` = VALUES(`DIAS_PAGAR_ENTIDAD`),
        `ESTADO_TRANSCRIPCION` = VALUES(`ESTADO_TRANSCRIPCION`),
        `CANAL_TRANSCRIPCION` = VALUES(`CANAL_TRANSCRIPCION`),
        `FECHA_TRANSCRIPCION` = VALUES(`FECHA_TRANSCRIPCION`),
        `ESTADO_SOLICITUD_PAGO` = VALUES(`ESTADO_SOLICITUD_PAGO`),
        `FECHA_SOLICITUD_PAGO` = VALUES(`FECHA_SOLICITUD_PAGO`),
        `VALOR_INCAPACIDAD` = VALUES(`VALOR_INCAPACIDAD`),
        `VALOR_RECIBIDO_ENTIDAD` = VALUES(`VALOR_RECIBIDO_ENTIDAD`),
        `VALOR_PAGADO_EMPRESA_TRABAJADOR` = VALUES(`VALOR_PAGADO_EMPRESA_TRABAJADOR`),
        `VALOR_PAGADO_TRABAJADOR` = VALUES(`VALOR_PAGADO_TRABAJADOR`),
        `FECHA_ULTIMO_PAGO` = VALUES(`FECHA_ULTIMO_PAGO`),
        `ESTADO_SEGUIMIENTO` = VALUES(`ESTADO_SEGUIMIENTO`),
        `OBSERVACIONES_SEGUIMIENTO` = VALUES(`OBSERVACIONES_SEGUIMIENTO`),
        `ID_ULTIMA_MODIFICACION_POR` = P_ID_USUARIO,
        `UPDATED_AT` = CURRENT_TIMESTAMP;

    INSERT INTO `bbf_novedad_historial`
    (`ID_NOVEDAD`,`ACCION`,`ESTADO_ANTERIOR`,`ESTADO_NUEVO`,`DETALLE`,`ID_USUARIO`)
    VALUES
    (
        P_ID_NOVEDAD,
        'ACTUALIZACION',
        V_ESTADO_NOVEDAD,
        V_ESTADO_NOVEDAD,
        CONCAT('Seguimiento de incapacidad actualizado. Estado: ',V_SEGUIMIENTO,'.'),
        P_ID_USUARIO
    );

    CALL `SP_BBF_INCAPACIDAD_SEGUIMIENTO_OBTENER`(P_ID_NOVEDAD);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_INCAPACIDAD_SEGUIMIENTO_OBTENER` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_INCAPACIDAD_SEGUIMIENTO_OBTENER`(
    IN P_ID_NOVEDAD BIGINT
)
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM `bbf_incapacidades`
        WHERE `ID_NOVEDAD` = P_ID_NOVEDAD
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La incapacidad no existe.';
    END IF;

    SELECT
        N.`ID_NOVEDAD`,
        I.`ID_INCAPACIDAD`,
        S.`ID_INCAPACIDAD_SEGUIMIENTO`,
        N.`ID_EMPLEADO`,
        E.`NUMERO_DOCUMENTO`,
        CONCAT_WS(' ',E.`NOMBRES`,E.`APELLIDOS`) AS `NOMBRE_COMPLETO`,
        N.`FECHA_INICIO`,
        N.`FECHA_FIN`,
        N.`NUMERO_DIAS`,
        I.`DIAGNOSTICO`,
        I.`CODIGO_CIE10`,
        I.`NUMERO_CERTIFICADO`,
        I.`NUMERO_RADICADO`,
        I.`FECHA_RADICACION`,
        I.`ORIGEN_INCAPACIDAD`,
        I.`ES_PRORROGA`,
        I.`ID_INCAPACIDAD_ORIGEN`,
        S.`ID_ENTIDAD_RESPONSABLE`,
        ES.`NOMBRE` AS `ENTIDAD_RESPONSABLE`,
        ES.`TIPO_ENTIDAD`,
        S.`DIAS_PAGADOS_EMPRESA`,
        S.`DIAS_PAGAR_ENTIDAD`,
        S.`ESTADO_TRANSCRIPCION`,
        S.`CANAL_TRANSCRIPCION`,
        S.`FECHA_TRANSCRIPCION`,
        S.`ESTADO_SOLICITUD_PAGO`,
        S.`FECHA_SOLICITUD_PAGO`,
        S.`VALOR_INCAPACIDAD`,
        S.`VALOR_RECIBIDO_ENTIDAD`,
        S.`VALOR_PAGADO_EMPRESA_TRABAJADOR`,
        S.`VALOR_ADEUDADO_ENTIDAD`,
        S.`VALOR_PAGADO_TRABAJADOR`,
        S.`FECHA_ULTIMO_PAGO`,
        S.`ESTADO_SEGUIMIENTO`,
        S.`OBSERVACIONES_SEGUIMIENTO`,
        S.`CREATED_AT`,
        S.`UPDATED_AT`
    FROM `bbf_incapacidades` I
    INNER JOIN `bbf_novedades_empleado` N
        ON N.`ID_NOVEDAD` = I.`ID_NOVEDAD`
    INNER JOIN `bbf_empleados` E
        ON E.`ID_EMPLEADO` = N.`ID_EMPLEADO`
    INNER JOIN `bbf_incapacidad_seguimiento` S
        ON S.`ID_INCAPACIDAD` = I.`ID_INCAPACIDAD`
    LEFT JOIN `bbf_entidades_seguridad_social` ES
        ON ES.`ID_ENTIDAD_SEGURIDAD_SOCIAL` = S.`ID_ENTIDAD_RESPONSABLE`
    WHERE I.`ID_NOVEDAD` = P_ID_NOVEDAD;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
