/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_NOTIFICACIONES_LISTAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_NOTIFICACIONES_LISTAR`(
    IN P_ID_USUARIO INT,
    IN P_SOLO_NO_LEIDAS TINYINT,
    IN P_LIMITE INT
)
BEGIN
    DECLARE V_LIMITE INT DEFAULT 50;
    SET V_LIMITE=CASE WHEN IFNULL(P_LIMITE,0) BETWEEN 1 AND 200 THEN P_LIMITE ELSE 50 END;

    SELECT N.ID_NOTIFICACION,T.CODIGO AS TIPO_CODIGO,T.NOMBRE AS TIPO_NOTIFICACION,T.MODULO,
           N.ID_EMPLEADO,N.TITULO,N.MENSAJE,N.PRIORIDAD,N.FECHA_EVENTO,N.FECHA_VENCIMIENTO,
           N.ESTADO,N.URL_ACCION,N.DATOS_JSON,D.LEIDA,D.FECHA_LECTURA,D.ARCHIVADA,N.CREATED_AT,
           CASE WHEN N.FECHA_VENCIMIENTO IS NULL THEN NULL ELSE DATEDIFF(N.FECHA_VENCIMIENTO,CURRENT_DATE) END AS DIAS_RESTANTES
    FROM bbf_notificacion_destinatarios D
    INNER JOIN bbf_notificaciones N ON N.ID_NOTIFICACION=D.ID_NOTIFICACION
    INNER JOIN bbf_tipos_notificacion T ON T.ID_TIPO_NOTIFICACION=N.ID_TIPO_NOTIFICACION
    WHERE D.ID_USUARIO=P_ID_USUARIO AND D.ARCHIVADA=0 AND N.ESTADO='ACTIVA'
      AND (IFNULL(P_SOLO_NO_LEIDAS,0)=0 OR D.LEIDA=0)
    ORDER BY FIELD(N.PRIORIDAD,'CRITICA','ALTA','MEDIA','BAJA'),
             N.FECHA_VENCIMIENTO IS NULL,N.FECHA_VENCIMIENTO,N.CREATED_AT DESC
    LIMIT V_LIMITE;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_NOTIFICACIONES_RESUMEN` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_NOTIFICACIONES_RESUMEN`(IN P_ID_USUARIO INT)
BEGIN
    SELECT COUNT(*) AS TOTAL_ACTIVAS,
           SUM(CASE WHEN D.LEIDA=0 THEN 1 ELSE 0 END) AS TOTAL_NO_LEIDAS,
           SUM(CASE WHEN N.PRIORIDAD='CRITICA' THEN 1 ELSE 0 END) AS TOTAL_CRITICAS,
           SUM(CASE WHEN T.MODULO='CONTRATACION' THEN 1 ELSE 0 END) AS TOTAL_CONTRATACION,
           SUM(CASE WHEN T.MODULO='CAPACITACIONES' THEN 1 ELSE 0 END) AS TOTAL_CAPACITACIONES,
           SUM(CASE WHEN T.MODULO='NOVEDADES' THEN 1 ELSE 0 END) AS TOTAL_NOVEDADES
    FROM bbf_notificacion_destinatarios D
    INNER JOIN bbf_notificaciones N ON N.ID_NOTIFICACION=D.ID_NOTIFICACION AND N.ESTADO='ACTIVA'
    INNER JOIN bbf_tipos_notificacion T ON T.ID_TIPO_NOTIFICACION=N.ID_TIPO_NOTIFICACION
    WHERE D.ID_USUARIO=P_ID_USUARIO AND D.ARCHIVADA=0;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_NOTIFICACIONES_SINCRONIZAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_NOTIFICACIONES_SINCRONIZAR`()
BEGIN
    DECLARE V_DIAS_CONTRATO INT DEFAULT 30;
    DECLARE V_DIAS_APELACION INT DEFAULT 5;

    SELECT CAST(VALOR AS UNSIGNED) INTO V_DIAS_CONTRATO
    FROM bbf_parametros_sistema
    WHERE CODIGO='NOTIFICACIONES_DIAS_VENCIMIENTO_CONTRATO' AND ACTIVO=1
      AND VIGENCIA_DESDE<=CURRENT_DATE AND (VIGENCIA_HASTA IS NULL OR VIGENCIA_HASTA>=CURRENT_DATE)
    ORDER BY VIGENCIA_DESDE DESC LIMIT 1;

    SELECT CAST(VALOR AS UNSIGNED) INTO V_DIAS_APELACION
    FROM bbf_parametros_sistema
    WHERE CODIGO='NOTIFICACIONES_DIAS_APELACION_SUSPENSION' AND ACTIVO=1
      AND VIGENCIA_DESDE<=CURRENT_DATE AND (VIGENCIA_HASTA IS NULL OR VIGENCIA_HASTA>=CURRENT_DATE)
    ORDER BY VIGENCIA_DESDE DESC LIMIT 1;

    -- Contratos proximos a vencer.
    INSERT INTO bbf_notificaciones
    (ID_TIPO_NOTIFICACION,CLAVE_UNICA,ID_EMPLEADO,TITULO,MENSAJE,PRIORIDAD,FECHA_EVENTO,FECHA_VENCIMIENTO,ESTADO,ORIGEN_TABLA,ORIGEN_ID,URL_ACCION,DATOS_JSON)
    SELECT T.ID_TIPO_NOTIFICACION,CONCAT('CONTRATO_VENCE:',C.ID_EMPLEADO_CONTRATO),C.ID_EMPLEADO,
           'Contrato proximo a vencer',
           CONCAT(E.NOMBRES,' ',E.APELLIDOS,' tiene contrato con vencimiento el ',DATE_FORMAT(C.FECHA_FIN,'%Y-%m-%d'),'.'),
           CASE WHEN DATEDIFF(C.FECHA_FIN,CURRENT_DATE)<=7 THEN 'CRITICA' ELSE 'ALTA' END,
           C.FECHA_FIN,C.FECHA_FIN,'ACTIVA','bbf_empleado_contratos',C.ID_EMPLEADO_CONTRATO,
           CONCAT('/admin/contracting/employees/',C.ID_EMPLEADO,'/contracts'),
           JSON_OBJECT('dias_restantes',DATEDIFF(C.FECHA_FIN,CURRENT_DATE),'numero_contrato',C.NUMERO_CONTRATO)
    FROM bbf_empleado_contratos C
    INNER JOIN bbf_empleados E ON E.ID_EMPLEADO=C.ID_EMPLEADO
    INNER JOIN bbf_tipos_notificacion T ON T.CODIGO='CONTRATO_PROXIMO_VENCER' AND T.ACTIVO=1
    WHERE C.ELIMINADO=0 AND C.ESTADO_CONTRATO='ACTIVO' AND C.FECHA_FIN IS NOT NULL
      AND C.FECHA_FIN BETWEEN CURRENT_DATE AND DATE_ADD(CURRENT_DATE,INTERVAL V_DIAS_CONTRATO DAY)
    ON DUPLICATE KEY UPDATE TITULO=VALUES(TITULO),MENSAJE=VALUES(MENSAJE),PRIORIDAD=VALUES(PRIORIDAD),FECHA_EVENTO=VALUES(FECHA_EVENTO),FECHA_VENCIMIENTO=VALUES(FECHA_VENCIMIENTO),ESTADO='ACTIVA',FECHA_RESOLUCION=NULL,URL_ACCION=VALUES(URL_ACCION),DATOS_JSON=VALUES(DATOS_JSON),UPDATED_AT=CURRENT_TIMESTAMP;

    -- Evaluaciones pendientes.
    INSERT INTO bbf_notificaciones
    (ID_TIPO_NOTIFICACION,CLAVE_UNICA,ID_EMPLEADO,TITULO,MENSAJE,PRIORIDAD,FECHA_EVENTO,FECHA_VENCIMIENTO,ESTADO,ORIGEN_TABLA,ORIGEN_ID,URL_ACCION)
    SELECT T.ID_TIPO_NOTIFICACION,CONCAT('CAP_EVAL_PEND:',P.ID_CAPACITACION_PARTICIPANTE),P.ID_EMPLEADO,
           'Evaluacion de capacitacion pendiente',
           CONCAT(E.NOMBRES,' ',E.APELLIDOS,' tiene una evaluacion pendiente en ',C.NOMBRE,'.'),
           'MEDIA',S.FECHA_FIN,S.FECHA_FIN,'ACTIVA','bbf_capacitacion_participantes',P.ID_CAPACITACION_PARTICIPANTE,
           CONCAT('/admin/trainings/sessions/',S.ID_CAPACITACION_SESION)
    FROM bbf_capacitacion_participantes P
    INNER JOIN bbf_capacitacion_sesiones S ON S.ID_CAPACITACION_SESION=P.ID_CAPACITACION_SESION
    INNER JOIN bbf_capacitaciones C ON C.ID_CAPACITACION=S.ID_CAPACITACION
    INNER JOIN bbf_empleados E ON E.ID_EMPLEADO=P.ID_EMPLEADO
    INNER JOIN bbf_tipos_notificacion T ON T.CODIGO='CAPACITACION_EVALUACION_PENDIENTE' AND T.ACTIVO=1
    WHERE P.ESTADO_EVALUACION IN ('PENDIENTE','EN_PROCESO') AND S.ESTADO<>'ANULADA'
    ON DUPLICATE KEY UPDATE MENSAJE=VALUES(MENSAJE),FECHA_EVENTO=VALUES(FECHA_EVENTO),FECHA_VENCIMIENTO=VALUES(FECHA_VENCIMIENTO),ESTADO='ACTIVA',FECHA_RESOLUCION=NULL,URL_ACCION=VALUES(URL_ACCION),UPDATED_AT=CURRENT_TIMESTAMP;

    -- Resultados no aprobados.
    INSERT INTO bbf_notificaciones
    (ID_TIPO_NOTIFICACION,CLAVE_UNICA,ID_EMPLEADO,TITULO,MENSAJE,PRIORIDAD,FECHA_EVENTO,ESTADO,ORIGEN_TABLA,ORIGEN_ID,URL_ACCION,DATOS_JSON)
    SELECT T.ID_TIPO_NOTIFICACION,CONCAT('CAP_NO_APROB:',R.ID_CAPACITACION_RESULTADO),P.ID_EMPLEADO,
           'Resultado de capacitacion no aprobado',
           CONCAT(E.NOMBRES,' ',E.APELLIDOS,' obtuvo resultado ',R.RESULTADO,' con puntaje ',COALESCE(R.PUNTAJE_FINAL,0),'.'),
           'ALTA',R.FECHA_RESULTADO,'ACTIVA','bbf_capacitacion_resultados',R.ID_CAPACITACION_RESULTADO,
           '/admin/trainings/follow-up',JSON_OBJECT('resultado',R.RESULTADO,'puntaje',R.PUNTAJE_FINAL,'requiere_compromiso',R.REQUIERE_COMPROMISO)
    FROM bbf_capacitacion_resultados R
    INNER JOIN bbf_capacitacion_participantes P ON P.ID_CAPACITACION_PARTICIPANTE=R.ID_CAPACITACION_PARTICIPANTE
    INNER JOIN bbf_empleados E ON E.ID_EMPLEADO=P.ID_EMPLEADO
    INNER JOIN bbf_tipos_notificacion T ON T.CODIGO='CAPACITACION_NO_APROBADA' AND T.ACTIVO=1
    WHERE R.RESULTADO IN ('NO_APROBADO','REQUIERE_REINDUCCION')
    ON DUPLICATE KEY UPDATE MENSAJE=VALUES(MENSAJE),PRIORIDAD=VALUES(PRIORIDAD),ESTADO='ACTIVA',FECHA_RESOLUCION=NULL,DATOS_JSON=VALUES(DATOS_JSON),UPDATED_AT=CURRENT_TIMESTAMP;

    -- Plazo de apelacion de suspension. Mientras no exista un campo especifico
    -- de apelacion, la alerta se calcula desde FECHA_INICIO y se resuelve al
    -- cerrar o anular la novedad.
    INSERT INTO bbf_notificaciones
    (ID_TIPO_NOTIFICACION,CLAVE_UNICA,ID_EMPLEADO,TITULO,MENSAJE,PRIORIDAD,FECHA_EVENTO,FECHA_VENCIMIENTO,ESTADO,ORIGEN_TABLA,ORIGEN_ID,URL_ACCION,DATOS_JSON)
    SELECT T.ID_TIPO_NOTIFICACION,CONCAT('SUSP_APELA:',N.ID_NOVEDAD),N.ID_EMPLEADO,
           'Plazo de apelacion de suspension',
           CONCAT('El plazo de apelacion de ',E.NOMBRES,' ',E.APELLIDOS,' vence el ',DATE_FORMAT(DATE_ADD(N.FECHA_INICIO,INTERVAL V_DIAS_APELACION DAY),'%Y-%m-%d'),'.'),
           'CRITICA',N.FECHA_INICIO,DATE_ADD(N.FECHA_INICIO,INTERVAL V_DIAS_APELACION DAY),'ACTIVA','bbf_novedades_empleado',N.ID_NOVEDAD,
           CONCAT('/admin/novelties/',N.ID_NOVEDAD),JSON_OBJECT('dias_apelacion',V_DIAS_APELACION)
    FROM bbf_novedades_empleado N
    INNER JOIN bbf_tipos_novedad TN ON TN.ID_TIPO_NOVEDAD=N.ID_TIPO_NOVEDAD AND TN.CODIGO='SUSPENSION'
    INNER JOIN bbf_empleados E ON E.ID_EMPLEADO=N.ID_EMPLEADO
    INNER JOIN bbf_tipos_notificacion T ON T.CODIGO='SUSPENSION_PLAZO_APELACION' AND T.ACTIVO=1
    WHERE N.ESTADO IN ('REGISTRADA','VALIDADA')
      AND DATE_ADD(N.FECHA_INICIO,INTERVAL V_DIAS_APELACION DAY)>=CURRENT_DATE
    ON DUPLICATE KEY UPDATE MENSAJE=VALUES(MENSAJE),FECHA_VENCIMIENTO=VALUES(FECHA_VENCIMIENTO),ESTADO='ACTIVA',FECHA_RESOLUCION=NULL,DATOS_JSON=VALUES(DATOS_JSON),UPDATED_AT=CURRENT_TIMESTAMP;

    -- Resolver automaticamente alertas cuyo origen ya no cumple la condicion.
    UPDATE bbf_notificaciones N
    INNER JOIN bbf_tipos_notificacion T ON T.ID_TIPO_NOTIFICACION=N.ID_TIPO_NOTIFICACION
    LEFT JOIN bbf_empleado_contratos C ON T.CODIGO='CONTRATO_PROXIMO_VENCER' AND C.ID_EMPLEADO_CONTRATO=N.ORIGEN_ID
    SET N.ESTADO='RESUELTA',N.FECHA_RESOLUCION=CURRENT_TIMESTAMP
    WHERE T.CODIGO='CONTRATO_PROXIMO_VENCER' AND N.ESTADO='ACTIVA'
      AND (C.ID_EMPLEADO_CONTRATO IS NULL OR C.ELIMINADO=1 OR C.ESTADO_CONTRATO<>'ACTIVO' OR C.FECHA_FIN<CURRENT_DATE OR C.FECHA_FIN>DATE_ADD(CURRENT_DATE,INTERVAL V_DIAS_CONTRATO DAY));

    UPDATE bbf_notificaciones N
    INNER JOIN bbf_tipos_notificacion T ON T.ID_TIPO_NOTIFICACION=N.ID_TIPO_NOTIFICACION
    INNER JOIN bbf_capacitacion_participantes P ON P.ID_CAPACITACION_PARTICIPANTE=N.ORIGEN_ID
    SET N.ESTADO='RESUELTA',N.FECHA_RESOLUCION=CURRENT_TIMESTAMP
    WHERE T.CODIGO='CAPACITACION_EVALUACION_PENDIENTE' AND N.ESTADO='ACTIVA' AND P.ESTADO_EVALUACION NOT IN ('PENDIENTE','EN_PROCESO');

    UPDATE bbf_notificaciones N
    INNER JOIN bbf_tipos_notificacion T ON T.ID_TIPO_NOTIFICACION=N.ID_TIPO_NOTIFICACION
    INNER JOIN bbf_capacitacion_resultados R ON R.ID_CAPACITACION_RESULTADO=N.ORIGEN_ID
    SET N.ESTADO='RESUELTA',N.FECHA_RESOLUCION=CURRENT_TIMESTAMP
    WHERE T.CODIGO='CAPACITACION_NO_APROBADA' AND N.ESTADO='ACTIVA' AND R.RESULTADO NOT IN ('NO_APROBADO','REQUIERE_REINDUCCION');

    UPDATE bbf_notificaciones N
    INNER JOIN bbf_tipos_notificacion T ON T.ID_TIPO_NOTIFICACION=N.ID_TIPO_NOTIFICACION
    INNER JOIN bbf_novedades_empleado NE ON NE.ID_NOVEDAD=N.ORIGEN_ID
    SET N.ESTADO='RESUELTA',N.FECHA_RESOLUCION=CURRENT_TIMESTAMP
    WHERE T.CODIGO='SUSPENSION_PLAZO_APELACION' AND N.ESTADO='ACTIVA'
      AND (NE.ESTADO IN ('CERRADA','ANULADA') OR N.FECHA_VENCIMIENTO<CURRENT_DATE);

    -- Crear bandejas personales para usuarios cuyos roles poseen el permiso
    -- funcional del modulo que origino cada alerta.
    INSERT IGNORE INTO bbf_notificacion_destinatarios (ID_NOTIFICACION,ID_USUARIO)
    SELECT DISTINCT N.ID_NOTIFICACION,U.ID_USUARIO
    FROM bbf_notificaciones N
    INNER JOIN bbf_tipos_notificacion T ON T.ID_TIPO_NOTIFICACION=N.ID_TIPO_NOTIFICACION
    INNER JOIN bbf_permisos P ON P.CODIGO=T.CODIGO_PERMISO_DESTINO AND P.ACTIVO=1
    INNER JOIN bbf_rol_permisos RP ON RP.ID_PERMISO=P.ID_PERMISO
    INNER JOIN bbf_usuario_roles UR ON UR.ID_ROL=RP.ID_ROL
    INNER JOIN bbf_usuarios U ON U.ID_USUARIO=UR.ID_USUARIO AND U.ESTADO='ACTIVO'
    WHERE N.ESTADO='ACTIVA';

    SELECT COUNT(*) AS TOTAL_ACTIVAS FROM bbf_notificaciones WHERE ESTADO='ACTIVA';
END ;;
DELIMITER ;
