CREATE  PROCEDURE `SP_BBF_NOTIFICACION_ARCHIVAR`(IN P_ID_NOTIFICACION BIGINT,IN P_ID_USUARIO INT)
BEGIN
    IF NOT EXISTS (SELECT 1 FROM bbf_notificacion_destinatarios WHERE ID_NOTIFICACION=P_ID_NOTIFICACION AND ID_USUARIO=P_ID_USUARIO) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Notificacion no encontrada para el usuario.';
    END IF;
    UPDATE bbf_notificacion_destinatarios SET ARCHIVADA=1,FECHA_ARCHIVADO=CURRENT_TIMESTAMP
    WHERE ID_NOTIFICACION=P_ID_NOTIFICACION AND ID_USUARIO=P_ID_USUARIO;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_NOTIFICACION_CREAR_MANUAL` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_NOTIFICACION_CREAR_MANUAL`(
    IN P_CODIGO_TIPO VARCHAR(80),IN P_ID_EMPLEADO INT,IN P_ID_USUARIO_DESTINO INT,
    IN P_TITULO VARCHAR(220),IN P_MENSAJE VARCHAR(1000),IN P_PRIORIDAD VARCHAR(20),
    IN P_FECHA_EVENTO DATE,IN P_FECHA_VENCIMIENTO DATE,IN P_URL_ACCION VARCHAR(500),IN P_ID_CREADO_POR INT
)
BEGIN
    DECLARE V_ID_TIPO INT;
    DECLARE V_ID_NOTIFICACION BIGINT;
    SELECT ID_TIPO_NOTIFICACION INTO V_ID_TIPO FROM bbf_tipos_notificacion WHERE CODIGO=P_CODIGO_TIPO AND ACTIVO=1 LIMIT 1;
    IF V_ID_TIPO IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tipo de notificacion inexistente o inactivo.'; END IF;
    IF P_TITULO IS NULL OR TRIM(P_TITULO)='' OR P_MENSAJE IS NULL OR TRIM(P_MENSAJE)='' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Titulo y mensaje son obligatorios.';
    END IF;
    INSERT INTO bbf_notificaciones
    (ID_TIPO_NOTIFICACION,CLAVE_UNICA,ID_EMPLEADO,TITULO,MENSAJE,PRIORIDAD,FECHA_EVENTO,FECHA_VENCIMIENTO,ESTADO,ORIGEN_TABLA,URL_ACCION,ID_CREADO_POR)
    VALUES(V_ID_TIPO,CONCAT('MANUAL:',UUID()),P_ID_EMPLEADO,TRIM(P_TITULO),TRIM(P_MENSAJE),
           CASE WHEN P_PRIORIDAD IN('BAJA','MEDIA','ALTA','CRITICA') THEN P_PRIORIDAD ELSE 'MEDIA' END,
           P_FECHA_EVENTO,P_FECHA_VENCIMIENTO,'ACTIVA','MANUAL',NULLIF(TRIM(P_URL_ACCION),''),P_ID_CREADO_POR);
    SET V_ID_NOTIFICACION=LAST_INSERT_ID();

    IF P_ID_USUARIO_DESTINO IS NOT NULL THEN
        INSERT INTO bbf_notificacion_destinatarios(ID_NOTIFICACION,ID_USUARIO) VALUES(V_ID_NOTIFICACION,P_ID_USUARIO_DESTINO);
    ELSE
        INSERT IGNORE INTO bbf_notificacion_destinatarios(ID_NOTIFICACION,ID_USUARIO)
        SELECT V_ID_NOTIFICACION,U.ID_USUARIO
        FROM bbf_usuarios U
        INNER JOIN bbf_usuario_roles UR ON UR.ID_USUARIO=U.ID_USUARIO
        INNER JOIN bbf_rol_permisos RP ON RP.ID_ROL=UR.ID_ROL
        INNER JOIN bbf_permisos P ON P.ID_PERMISO=RP.ID_PERMISO AND P.CODIGO='NOTIFICACIONES_VER'
        WHERE U.ESTADO='ACTIVO';
    END IF;
    SELECT * FROM bbf_notificaciones WHERE ID_NOTIFICACION=V_ID_NOTIFICACION;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
