DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_NOTIFICACION_MARCAR_LEIDA`(IN P_ID_NOTIFICACION BIGINT,IN P_ID_USUARIO INT,IN P_LEIDA TINYINT)
BEGIN
    IF NOT EXISTS (SELECT 1 FROM bbf_notificacion_destinatarios WHERE ID_NOTIFICACION=P_ID_NOTIFICACION AND ID_USUARIO=P_ID_USUARIO) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Notificacion no encontrada para el usuario.';
    END IF;
    UPDATE bbf_notificacion_destinatarios
    SET LEIDA=IFNULL(P_LEIDA,1),FECHA_LECTURA=CASE WHEN IFNULL(P_LEIDA,1)=1 THEN CURRENT_TIMESTAMP ELSE NULL END
    WHERE ID_NOTIFICACION=P_ID_NOTIFICACION AND ID_USUARIO=P_ID_USUARIO;
    SELECT * FROM bbf_notificacion_destinatarios WHERE ID_NOTIFICACION=P_ID_NOTIFICACION AND ID_USUARIO=P_ID_USUARIO;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_NOTIFICACION_RESOLVER` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_NOTIFICACION_RESOLVER`(IN P_ID_NOTIFICACION BIGINT,IN P_ID_USUARIO INT)
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM bbf_notificacion_destinatarios D
        WHERE D.ID_NOTIFICACION=P_ID_NOTIFICACION AND D.ID_USUARIO=P_ID_USUARIO
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Notificacion no encontrada para el usuario.';
    END IF;
    UPDATE bbf_notificaciones
    SET ESTADO='RESUELTA',FECHA_RESOLUCION=CURRENT_TIMESTAMP
    WHERE ID_NOTIFICACION=P_ID_NOTIFICACION AND ESTADO='ACTIVA';
    SELECT * FROM bbf_notificaciones WHERE ID_NOTIFICACION=P_ID_NOTIFICACION;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
