/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_NOVEDADES_LISTAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_NOVEDADES_LISTAR`(
    IN P_ID_EMPLEADO INT,
    IN P_CODIGO_TIPO VARCHAR(50),
    IN P_ESTADO VARCHAR(30),
    IN P_FECHA_DESDE DATE,
    IN P_FECHA_HASTA DATE
)
BEGIN
    SELECT
        N.ID_NOVEDAD, N.ID_EMPLEADO, E.NUMERO_DOCUMENTO,
        CONCAT_WS(' ',E.NOMBRES,E.APELLIDOS) AS NOMBRE_COMPLETO,
        E.ID_AREA, A.NOMBRE AS AREA, E.ID_CARGO, C.NOMBRE AS CARGO,
        N.ID_TIPO_NOVEDAD, TN.CODIGO AS CODIGO_TIPO_NOVEDAD,
        TN.NOMBRE AS TIPO_NOVEDAD, TN.ES_INCAPACIDAD,
        N.FECHA_INICIO, N.FECHA_FIN, N.NUMERO_DIAS, N.MOTIVO,
        N.OBSERVACIONES, N.ESTADO, N.ID_REGISTRADO_POR,
        U.NOMBRE_USUARIO AS REGISTRADO_POR, N.CREATED_AT, N.UPDATED_AT,
        I.ID_INCAPACIDAD, I.ID_EPS, EPS.NOMBRE AS EPS,
        I.NUMERO_CERTIFICADO, I.NUMERO_RADICADO, I.DIAGNOSTICO,
        I.CODIGO_CIE10, I.ORIGEN_INCAPACIDAD, I.ENTIDAD_EMISORA,
        I.ES_PRORROGA, I.ID_INCAPACIDAD_ORIGEN, I.FECHA_RADICACION,
        (SELECT COUNT(*) FROM bbf_novedad_evidencias EV
         WHERE EV.ID_NOVEDAD = N.ID_NOVEDAD) AS TOTAL_EVIDENCIAS
    FROM bbf_novedades_empleado N
    INNER JOIN bbf_empleados E ON E.ID_EMPLEADO = N.ID_EMPLEADO
    INNER JOIN bbf_tipos_novedad TN ON TN.ID_TIPO_NOVEDAD = N.ID_TIPO_NOVEDAD
    LEFT JOIN bbf_areas A ON A.ID_AREA = E.ID_AREA
    LEFT JOIN bbf_cargos C ON C.ID_CARGO = E.ID_CARGO
    LEFT JOIN bbf_usuarios U ON U.ID_USUARIO = N.ID_REGISTRADO_POR
    LEFT JOIN bbf_incapacidades I ON I.ID_NOVEDAD = N.ID_NOVEDAD
    LEFT JOIN bbf_entidades_seguridad_social EPS
        ON EPS.ID_ENTIDAD_SEGURIDAD_SOCIAL = I.ID_EPS
    WHERE (P_ID_EMPLEADO IS NULL OR P_ID_EMPLEADO = 0 OR N.ID_EMPLEADO = P_ID_EMPLEADO)
      AND (P_CODIGO_TIPO IS NULL OR TRIM(P_CODIGO_TIPO) = '' OR TN.CODIGO = UPPER(TRIM(P_CODIGO_TIPO)))
      AND (P_ESTADO IS NULL OR TRIM(P_ESTADO) = '' OR N.ESTADO = UPPER(TRIM(P_ESTADO)))
      AND (P_FECHA_DESDE IS NULL OR COALESCE(N.FECHA_FIN,N.FECHA_INICIO) >= P_FECHA_DESDE)
      AND (P_FECHA_HASTA IS NULL OR N.FECHA_INICIO <= P_FECHA_HASTA)
    ORDER BY N.FECHA_INICIO DESC, N.ID_NOVEDAD DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_NOVEDADES_TIPOS_LISTAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
