/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_NOVEDAD_ACTUALIZAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_NOVEDAD_ACTUALIZAR`(
    IN P_ID_NOVEDAD BIGINT,
    IN P_FECHA_INICIO DATE,
    IN P_FECHA_FIN DATE,
    IN P_MOTIVO VARCHAR(500),
    IN P_OBSERVACIONES TEXT,
    IN P_ID_USUARIO INT
)
BEGIN
    DECLARE V_ESTADO VARCHAR(30);
    DECLARE V_REQUIERE_FIN TINYINT DEFAULT 0;
    DECLARE V_ES_INCAPACIDAD TINYINT DEFAULT 0;
    DECLARE V_DIAS INT;

    SELECT N.ESTADO,TN.REQUIERE_FECHA_FIN,TN.ES_INCAPACIDAD
      INTO V_ESTADO,V_REQUIERE_FIN,V_ES_INCAPACIDAD
    FROM bbf_novedades_empleado N
    INNER JOIN bbf_tipos_novedad TN ON TN.ID_TIPO_NOVEDAD=N.ID_TIPO_NOVEDAD
    WHERE N.ID_NOVEDAD=P_ID_NOVEDAD LIMIT 1;

    IF V_ESTADO IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La novedad no existe.';
    END IF;
    IF V_ES_INCAPACIDAD=1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Use SP_BBF_INCAPACIDAD_ACTUALIZAR para actualizar incapacidades.';
    END IF;
    IF V_ESTADO IN ('CERRADA','ANULADA') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No se puede editar una novedad cerrada o anulada.';
    END IF;
    IF P_FECHA_INICIO IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La fecha de inicio es obligatoria.';
    END IF;
    IF V_REQUIERE_FIN=1 AND P_FECHA_FIN IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El tipo de novedad requiere fecha de finalizacion.';
    END IF;
    IF P_FECHA_FIN IS NOT NULL AND P_FECHA_FIN<P_FECHA_INICIO THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La fecha final no puede ser anterior a la fecha inicial.';
    END IF;

    SET V_DIAS=DATEDIFF(COALESCE(P_FECHA_FIN,P_FECHA_INICIO),P_FECHA_INICIO)+1;
    UPDATE bbf_novedades_empleado SET
        FECHA_INICIO=P_FECHA_INICIO,FECHA_FIN=P_FECHA_FIN,NUMERO_DIAS=V_DIAS,
        MOTIVO=NULLIF(TRIM(P_MOTIVO),''),OBSERVACIONES=NULLIF(TRIM(P_OBSERVACIONES),''),
        ID_ULTIMA_MODIFICACION_POR=P_ID_USUARIO,UPDATED_AT=CURRENT_TIMESTAMP
    WHERE ID_NOVEDAD=P_ID_NOVEDAD;

    INSERT INTO bbf_novedad_historial
    (ID_NOVEDAD,ACCION,ESTADO_ANTERIOR,ESTADO_NUEVO,DETALLE,ID_USUARIO)
    VALUES (P_ID_NOVEDAD,'ACTUALIZACION',V_ESTADO,V_ESTADO,'Datos de la novedad actualizados.',P_ID_USUARIO);
    SELECT P_ID_NOVEDAD AS ID_NOVEDAD,V_DIAS AS NUMERO_DIAS;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_NOVEDAD_CAMBIAR_ESTADO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_NOVEDAD_CAMBIAR_ESTADO`(
    IN P_ID_NOVEDAD BIGINT,
    IN P_NUEVO_ESTADO VARCHAR(30),
    IN P_OBSERVACION VARCHAR(500),
    IN P_ID_USUARIO INT
)
BEGIN
    DECLARE V_ANTERIOR VARCHAR(30);
    DECLARE V_NUEVO VARCHAR(30);
    DECLARE V_REQUIERE_SOPORTE TINYINT DEFAULT 0;
    SELECT N.ESTADO,TN.REQUIERE_SOPORTE INTO V_ANTERIOR,V_REQUIERE_SOPORTE
    FROM bbf_novedades_empleado N
    INNER JOIN bbf_tipos_novedad TN ON TN.ID_TIPO_NOVEDAD=N.ID_TIPO_NOVEDAD
    WHERE N.ID_NOVEDAD=P_ID_NOVEDAD LIMIT 1;
    IF V_ANTERIOR IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La novedad no existe.';
    END IF;
    SET V_NUEVO=UPPER(TRIM(P_NUEVO_ESTADO));
    IF V_NUEVO NOT IN ('REGISTRADA','VALIDADA','CERRADA','ANULADA') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El nuevo estado no es valido.';
    END IF;
    IF V_ANTERIOR='ANULADA' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Una novedad anulada no puede cambiar de estado.';
    END IF;
    IF V_NUEVO='ANULADA' AND (P_OBSERVACION IS NULL OR TRIM(P_OBSERVACION)='') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El motivo de anulacion es obligatorio.';
    END IF;
    IF V_NUEVO IN ('VALIDADA','CERRADA') AND V_REQUIERE_SOPORTE=1
       AND NOT EXISTS (SELECT 1 FROM bbf_novedad_evidencias WHERE ID_NOVEDAD=P_ID_NOVEDAD) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Debe adjuntar al menos un soporte antes de validar o cerrar la novedad.';
    END IF;

    UPDATE bbf_novedades_empleado SET
        ESTADO=V_NUEVO,
        ID_ULTIMA_MODIFICACION_POR=P_ID_USUARIO,
        ID_ANULADO_POR=CASE WHEN V_NUEVO='ANULADA' THEN P_ID_USUARIO ELSE ID_ANULADO_POR END,
        FECHA_ANULACION=CASE WHEN V_NUEVO='ANULADA' THEN CURRENT_TIMESTAMP ELSE FECHA_ANULACION END,
        MOTIVO_ANULACION=CASE WHEN V_NUEVO='ANULADA' THEN TRIM(P_OBSERVACION) ELSE MOTIVO_ANULACION END,
        UPDATED_AT=CURRENT_TIMESTAMP
    WHERE ID_NOVEDAD=P_ID_NOVEDAD;

    INSERT INTO bbf_novedad_historial
    (ID_NOVEDAD,ACCION,ESTADO_ANTERIOR,ESTADO_NUEVO,DETALLE,ID_USUARIO)
    VALUES (P_ID_NOVEDAD,CASE WHEN V_NUEVO='ANULADA' THEN 'ANULACION' ELSE 'CAMBIO_ESTADO' END,
            V_ANTERIOR,V_NUEVO,NULLIF(TRIM(P_OBSERVACION),''),P_ID_USUARIO);
    SELECT P_ID_NOVEDAD AS ID_NOVEDAD, V_ANTERIOR AS ESTADO_ANTERIOR, V_NUEVO AS ESTADO_NUEVO;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_NOVEDAD_CREAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_NOVEDAD_CREAR`(
    IN P_ID_EMPLEADO INT,
    IN P_CODIGO_TIPO VARCHAR(50),
    IN P_FECHA_INICIO DATE,
    IN P_FECHA_FIN DATE,
    IN P_MOTIVO VARCHAR(500),
    IN P_OBSERVACIONES TEXT,
    IN P_ID_USUARIO INT
)
BEGIN
    DECLARE V_ID_TIPO INT DEFAULT NULL;
    DECLARE V_REQUIERE_FIN TINYINT DEFAULT 0;
    DECLARE V_ES_INCAPACIDAD TINYINT DEFAULT 0;
    DECLARE V_DIAS INT DEFAULT 1;
    DECLARE V_ID_NOVEDAD BIGINT;

    IF NOT EXISTS (SELECT 1 FROM bbf_empleados WHERE ID_EMPLEADO=P_ID_EMPLEADO AND IFNULL(ELIMINADO,0)=0) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El empleado no existe o fue eliminado.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM bbf_usuarios WHERE ID_USUARIO=P_ID_USUARIO) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El usuario registrador no existe.';
    END IF;

    SELECT ID_TIPO_NOVEDAD, REQUIERE_FECHA_FIN, ES_INCAPACIDAD
      INTO V_ID_TIPO, V_REQUIERE_FIN, V_ES_INCAPACIDAD
    FROM bbf_tipos_novedad
    WHERE CODIGO=UPPER(TRIM(P_CODIGO_TIPO)) AND ACTIVO=1 LIMIT 1;

    IF V_ID_TIPO IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El tipo de novedad no existe o esta inactivo.';
    END IF;
    IF V_ES_INCAPACIDAD=1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Use SP_BBF_INCAPACIDAD_CREAR para registrar incapacidades.';
    END IF;
    IF P_FECHA_INICIO IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La fecha de inicio es obligatoria.';
    END IF;
    IF V_REQUIERE_FIN=1 AND P_FECHA_FIN IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El tipo de novedad requiere fecha de finalizacion.';
    END IF;
    IF P_FECHA_FIN IS NOT NULL AND P_FECHA_FIN < P_FECHA_INICIO THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La fecha final no puede ser anterior a la fecha inicial.';
    END IF;

    SET V_DIAS = DATEDIFF(COALESCE(P_FECHA_FIN,P_FECHA_INICIO),P_FECHA_INICIO)+1;
    INSERT INTO bbf_novedades_empleado
    (ID_EMPLEADO,ID_TIPO_NOVEDAD,FECHA_INICIO,FECHA_FIN,NUMERO_DIAS,MOTIVO,OBSERVACIONES,ID_REGISTRADO_POR)
    VALUES
    (P_ID_EMPLEADO,V_ID_TIPO,P_FECHA_INICIO,P_FECHA_FIN,V_DIAS,NULLIF(TRIM(P_MOTIVO),''),NULLIF(TRIM(P_OBSERVACIONES),''),P_ID_USUARIO);
    SET V_ID_NOVEDAD=LAST_INSERT_ID();

    INSERT INTO bbf_novedad_historial
    (ID_NOVEDAD,ACCION,ESTADO_NUEVO,DETALLE,ID_USUARIO)
    VALUES (V_ID_NOVEDAD,'CREACION','REGISTRADA','Novedad registrada.',P_ID_USUARIO);

    SELECT V_ID_NOVEDAD AS ID_NOVEDAD;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
