/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_NOVEDAD_EVIDENCIA_AGREGAR`(
    IN P_ID_NOVEDAD BIGINT,
    IN P_TIPO_EVIDENCIA VARCHAR(30),
    IN P_NOMBRE_ARCHIVO VARCHAR(255),
    IN P_NOMBRE_ORIGINAL VARCHAR(255),
    IN P_ARCHIVO_URL VARCHAR(500),
    IN P_ARCHIVO_RUTA VARCHAR(500),
    IN P_MIME_TYPE VARCHAR(100),
    IN P_PESO_BYTES BIGINT,
    IN P_OBSERVACIONES VARCHAR(500),
    IN P_ID_USUARIO INT
)
BEGIN
    DECLARE V_TIPO VARCHAR(30);
    DECLARE V_ID BIGINT;
    IF NOT EXISTS (SELECT 1 FROM bbf_novedades_empleado WHERE ID_NOVEDAD=P_ID_NOVEDAD AND ESTADO<>'ANULADA') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La novedad no existe o esta anulada.';
    END IF;
    IF (P_ARCHIVO_URL IS NULL OR TRIM(P_ARCHIVO_URL)='') = (P_ARCHIVO_RUTA IS NULL OR TRIM(P_ARCHIVO_RUTA)='') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Debe registrar una URL o una ruta fisica, pero no ambas.';
    END IF;
    IF P_NOMBRE_ARCHIVO IS NULL OR TRIM(P_NOMBRE_ARCHIVO)='' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El nombre del soporte es obligatorio.';
    END IF;
    IF P_PESO_BYTES IS NOT NULL AND P_PESO_BYTES<=0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El peso del archivo debe ser mayor que cero.';
    END IF;
    SET V_TIPO=UPPER(TRIM(IFNULL(P_TIPO_EVIDENCIA,'SOPORTE')));
    IF V_TIPO NOT IN ('SOPORTE','TRANSCRIPCION','PRORROGA','OTRO') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El tipo de evidencia no es valido.';
    END IF;

    INSERT INTO bbf_novedad_evidencias
    (ID_NOVEDAD,TIPO_EVIDENCIA,NOMBRE_ARCHIVO,NOMBRE_ORIGINAL,ARCHIVO_URL,ARCHIVO_RUTA,
     MIME_TYPE,PESO_BYTES,OBSERVACIONES,ID_CARGADO_POR)
    VALUES
    (P_ID_NOVEDAD,V_TIPO,TRIM(P_NOMBRE_ARCHIVO),NULLIF(TRIM(P_NOMBRE_ORIGINAL),''),
     NULLIF(TRIM(P_ARCHIVO_URL),''),NULLIF(TRIM(P_ARCHIVO_RUTA),''),P_MIME_TYPE,P_PESO_BYTES,
     NULLIF(TRIM(P_OBSERVACIONES),''),P_ID_USUARIO);
    SET V_ID=LAST_INSERT_ID();

    INSERT INTO bbf_novedad_historial
    (ID_NOVEDAD,ACCION,DETALLE,ID_USUARIO)
    VALUES (P_ID_NOVEDAD,'EVIDENCIA_AGREGADA',CONCAT('Soporte agregado: ',TRIM(P_NOMBRE_ARCHIVO)),P_ID_USUARIO);
    SELECT V_ID AS ID_NOVEDAD_EVIDENCIA;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
