CREATE  PROCEDURE `SP_BBF_NOVEDAD_HISTORIAL_LISTAR`(IN P_ID_NOVEDAD BIGINT)
BEGIN
    SELECT H.*,U.NOMBRE_USUARIO
    FROM bbf_novedad_historial H
    INNER JOIN bbf_usuarios U ON U.ID_USUARIO=H.ID_USUARIO
    WHERE H.ID_NOVEDAD=P_ID_NOVEDAD
    ORDER BY H.CREATED_AT DESC,H.ID_NOVEDAD_HISTORIAL DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_NOVEDAD_OBTENER` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_NOVEDAD_OBTENER`(IN P_ID_NOVEDAD BIGINT)
BEGIN
    IF NOT EXISTS (SELECT 1 FROM bbf_novedades_empleado WHERE ID_NOVEDAD = P_ID_NOVEDAD) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La novedad no existe.';
    END IF;

    SELECT N.*, TN.CODIGO AS CODIGO_TIPO_NOVEDAD, TN.NOMBRE AS TIPO_NOVEDAD,
           TN.REQUIERE_FECHA_FIN, TN.REQUIERE_SOPORTE, TN.ES_INCAPACIDAD,
           E.NUMERO_DOCUMENTO, CONCAT_WS(' ',E.NOMBRES,E.APELLIDOS) AS NOMBRE_COMPLETO,
           I.ID_INCAPACIDAD, I.ID_EPS, EPS.NOMBRE AS EPS,
           I.NUMERO_CERTIFICADO, I.NUMERO_RADICADO, I.DIAGNOSTICO,
           I.CODIGO_CIE10, I.ORIGEN_INCAPACIDAD, I.ENTIDAD_EMISORA,
           I.ES_PRORROGA, I.ID_INCAPACIDAD_ORIGEN, I.FECHA_RADICACION,
           I.OBSERVACIONES_MEDICAS
    FROM bbf_novedades_empleado N
    INNER JOIN bbf_tipos_novedad TN ON TN.ID_TIPO_NOVEDAD = N.ID_TIPO_NOVEDAD
    INNER JOIN bbf_empleados E ON E.ID_EMPLEADO = N.ID_EMPLEADO
    LEFT JOIN bbf_incapacidades I ON I.ID_NOVEDAD = N.ID_NOVEDAD
    LEFT JOIN bbf_entidades_seguridad_social EPS
        ON EPS.ID_ENTIDAD_SEGURIDAD_SOCIAL = I.ID_EPS
    WHERE N.ID_NOVEDAD = P_ID_NOVEDAD;

    SELECT * FROM bbf_novedad_evidencias
    WHERE ID_NOVEDAD = P_ID_NOVEDAD ORDER BY ID_NOVEDAD_EVIDENCIA;

    SELECT H.*, U.NOMBRE_USUARIO
    FROM bbf_novedad_historial H
    INNER JOIN bbf_usuarios U ON U.ID_USUARIO = H.ID_USUARIO
    WHERE H.ID_NOVEDAD = P_ID_NOVEDAD
    ORDER BY H.CREATED_AT DESC, H.ID_NOVEDAD_HISTORIAL DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_PARAMETROS_LISTAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_PARAMETROS_LISTAR`(
    IN P_GRUPO VARCHAR(100),
    IN P_CODIGO VARCHAR(100),
    IN P_INCLUIR_INACTIVOS TINYINT
)
BEGIN
    SELECT
        PS.`ID_PARAMETRO`,
        PS.`CODIGO`,
        PS.`NOMBRE`,
        PS.`GRUPO`,
        PS.`DESCRIPCION`,
        PS.`TIPO_DATO`,
        PS.`VALOR`,
        PS.`UNIDAD_MEDIDA`,
        PS.`VIGENCIA_DESDE`,
        PS.`VIGENCIA_HASTA`,
        PS.`ACTIVO`,
        PS.`EDITABLE`,
        PS.`ID_CREADO_POR`,
        UC.`NOMBRE_USUARIO` AS `CREADO_POR`,
        PS.`ID_ACTUALIZADO_POR`,
        UA.`NOMBRE_USUARIO` AS `ACTUALIZADO_POR`,
        PS.`CREATED_AT`,
        PS.`UPDATED_AT`

    FROM `bbf_parametros_sistema` PS

    LEFT JOIN `bbf_usuarios` UC
        ON UC.`ID_USUARIO` = PS.`ID_CREADO_POR`

    LEFT JOIN `bbf_usuarios` UA
        ON UA.`ID_USUARIO` = PS.`ID_ACTUALIZADO_POR`

    WHERE (
        NULLIF(TRIM(P_GRUPO), '') IS NULL
        OR PS.`GRUPO` = UPPER(TRIM(P_GRUPO))
    )
    AND (
        NULLIF(TRIM(P_CODIGO), '') IS NULL
        OR PS.`CODIGO` = UPPER(TRIM(P_CODIGO))
    )
    AND (
        IFNULL(P_INCLUIR_INACTIVOS, 0) = 1
        OR PS.`ACTIVO` = 1
    )

    ORDER BY
        PS.`GRUPO`,
        PS.`CODIGO`,
        PS.`VIGENCIA_DESDE` DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_PARAMETRO_VIGENTE_OBTENER` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_PARAMETRO_VIGENTE_OBTENER`(
    IN P_CODIGO VARCHAR(100),
    IN P_FECHA DATE
)
BEGIN
    DECLARE V_FECHA DATE;

    SET V_FECHA = IFNULL(P_FECHA, CURRENT_DATE());

    SELECT
        PS.`ID_PARAMETRO`,
        PS.`CODIGO`,
        PS.`NOMBRE`,
        PS.`GRUPO`,
        PS.`DESCRIPCION`,
        PS.`TIPO_DATO`,
        PS.`VALOR`,
        PS.`UNIDAD_MEDIDA`,
        PS.`VIGENCIA_DESDE`,
        PS.`VIGENCIA_HASTA`,
        PS.`ACTIVO`,
        PS.`EDITABLE`,
        PS.`CREATED_AT`,
        PS.`UPDATED_AT`

    FROM `bbf_parametros_sistema` PS

    WHERE PS.`CODIGO` = UPPER(TRIM(P_CODIGO))
      AND PS.`ACTIVO` = 1
      AND PS.`VIGENCIA_DESDE` <= V_FECHA
      AND (
          PS.`VIGENCIA_HASTA` IS NULL
          OR PS.`VIGENCIA_HASTA` >= V_FECHA
      )

    ORDER BY
        PS.`VIGENCIA_DESDE` DESC,
        PS.`ID_PARAMETRO` DESC

    LIMIT 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
