/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_PARAM_AREAS_GUARDAR`(
    IN P_ID_AREA INT,
    IN P_NOMBRE VARCHAR(150),
    IN P_DESCRIPCION TEXT,
    IN P_ACTIVO TINYINT
)
BEGIN

    DECLARE V_ID INT;

    IF NULLIF(TRIM(P_NOMBRE), '') IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El nombre del área es obligatorio.';
    END IF;

    IF IFNULL(P_ID_AREA, 0) = 0 THEN

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_areas`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Ya existe un área con ese nombre.';
        END IF;

        INSERT INTO `bbf_areas`
        (
            `NOMBRE`,
            `DESCRIPCION`,
            `ACTIVO`
        )
        VALUES
        (
            TRIM(P_NOMBRE),
            NULLIF(TRIM(P_DESCRIPCION), ''),
            IFNULL(P_ACTIVO, 1)
        );

        SET V_ID = LAST_INSERT_ID();

    ELSE

        IF NOT EXISTS
        (
            SELECT 1
            FROM `bbf_areas`
            WHERE `ID_AREA` = P_ID_AREA
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El área indicada no existe.';
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_areas`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
              AND `ID_AREA` <> P_ID_AREA
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Ya existe otra área con ese nombre.';
        END IF;

        UPDATE `bbf_areas`
        SET
            `NOMBRE` = TRIM(P_NOMBRE),
            `DESCRIPCION` =
                NULLIF(TRIM(P_DESCRIPCION), ''),
            `ACTIVO` =
                IFNULL(P_ACTIVO, `ACTIVO`),
            `UPDATED_AT` = CURRENT_TIMESTAMP
        WHERE `ID_AREA` = P_ID_AREA;

        SET V_ID = P_ID_AREA;

    END IF;

    SELECT *
    FROM `bbf_areas`
    WHERE `ID_AREA` = V_ID;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_PARAM_AREAS_LISTAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_PARAM_AREAS_LISTAR`(
    IN P_INCLUIR_INACTIVOS TINYINT
)
BEGIN

    SELECT
        `ID_AREA`,
        `NOMBRE`,
        `DESCRIPCION`,
        `ACTIVO`,
        `CREATED_AT`,
        `UPDATED_AT`
    FROM `bbf_areas`
    WHERE
        IFNULL(P_INCLUIR_INACTIVOS, 0) = 1
        OR `ACTIVO` = 1
    ORDER BY `NOMBRE`;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
