/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_PARAM_CARGOS_GUARDAR`(
    IN P_ID_CARGO INT,
    IN P_NOMBRE VARCHAR(150),
    IN P_DESCRIPCION TEXT,
    IN P_ACTIVO TINYINT
)
BEGIN

    DECLARE V_ID INT;

    IF NULLIF(TRIM(P_NOMBRE), '') IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El nombre del cargo es obligatorio.';
    END IF;

    IF IFNULL(P_ID_CARGO, 0) = 0 THEN

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_cargos`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Ya existe un cargo con ese nombre.';
        END IF;

        INSERT INTO `bbf_cargos`
        (
            `NOMBRE`,
            `DESCRIPCION`,
            `ACTIVO`
        )
        VALUES
        (
            TRIM(P_NOMBRE),
            NULLIF(TRIM(P_DESCRIPCION), ''),
            IFNULL(P_ACTIVO, 1)
        );

        SET V_ID = LAST_INSERT_ID();

    ELSE

        IF NOT EXISTS
        (
            SELECT 1
            FROM `bbf_cargos`
            WHERE `ID_CARGO` = P_ID_CARGO
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El cargo indicado no existe.';
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_cargos`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
              AND `ID_CARGO` <> P_ID_CARGO
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Ya existe otro cargo con ese nombre.';
        END IF;

        UPDATE `bbf_cargos`
        SET
            `NOMBRE` = TRIM(P_NOMBRE),
            `DESCRIPCION` =
                NULLIF(TRIM(P_DESCRIPCION), ''),
            `ACTIVO` =
                IFNULL(P_ACTIVO, `ACTIVO`),
            `UPDATED_AT` = CURRENT_TIMESTAMP
        WHERE `ID_CARGO` = P_ID_CARGO;

        SET V_ID = P_ID_CARGO;

    END IF;

    SELECT *
    FROM `bbf_cargos`
    WHERE `ID_CARGO` = V_ID;

END ;;
DELIMITER ;
