CREATE  PROCEDURE `SP_BBF_PARAM_CARGOS_LISTAR`(
    IN P_INCLUIR_INACTIVOS TINYINT
)
BEGIN

    SELECT
        `ID_CARGO`,
        `NOMBRE`,
        `DESCRIPCION`,
        `ACTIVO`,
        `CREATED_AT`,
        `UPDATED_AT`
    FROM `bbf_cargos`
    WHERE
        IFNULL(P_INCLUIR_INACTIVOS, 0) = 1
        OR `ACTIVO` = 1
    ORDER BY `NOMBRE`;

END ;;
