DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_PARAM_DEPARTAMENTOS_LISTAR`(IN P_INCLUIR_INACTIVOS TINYINT)
BEGIN
    SELECT D.ID_DEPARTAMENTO, D.CODIGO_DANE, D.NOMBRE, D.ACTIVO,
           COUNT(M.ID_MUNICIPIO) TOTAL_MUNICIPIOS,
           COALESCE(SUM(M.ACTIVO = 1), 0) MUNICIPIOS_ACTIVOS
    FROM bbf_departamentos D
    LEFT JOIN bbf_municipios M ON M.ID_DEPARTAMENTO = D.ID_DEPARTAMENTO
    WHERE IFNULL(P_INCLUIR_INACTIVOS, 0) = 1 OR D.ACTIVO = 1
    GROUP BY D.ID_DEPARTAMENTO, D.CODIGO_DANE, D.NOMBRE, D.ACTIVO
    ORDER BY D.NOMBRE;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_PARAM_DEPARTAMENTO_GUARDAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_PARAM_DEPARTAMENTO_GUARDAR`(
 IN P_ID_DEPARTAMENTO INT, IN P_CODIGO_DANE VARCHAR(2), IN P_NOMBRE VARCHAR(150), IN P_ACTIVO TINYINT)
BEGIN
    SET P_CODIGO_DANE = TRIM(P_CODIGO_DANE); SET P_NOMBRE = TRIM(P_NOMBRE);
    IF P_CODIGO_DANE NOT REGEXP '^[0-9]{2}$' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El codigo DANE del departamento debe contener exactamente 2 digitos.'; END IF;
    IF P_NOMBRE IS NULL OR P_NOMBRE = '' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El nombre del departamento es obligatorio.'; END IF;
    IF EXISTS(SELECT 1 FROM bbf_departamentos WHERE CODIGO_DANE=P_CODIGO_DANE AND (P_ID_DEPARTAMENTO IS NULL OR ID_DEPARTAMENTO<>P_ID_DEPARTAMENTO)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Ya existe un departamento con ese codigo DANE.'; END IF;
    IF EXISTS(SELECT 1 FROM bbf_departamentos WHERE UPPER(NOMBRE)=UPPER(P_NOMBRE) AND (P_ID_DEPARTAMENTO IS NULL OR ID_DEPARTAMENTO<>P_ID_DEPARTAMENTO)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Ya existe un departamento con ese nombre.'; END IF;
    IF P_ID_DEPARTAMENTO IS NOT NULL AND IFNULL(P_ACTIVO,1)=0 AND EXISTS(SELECT 1 FROM bbf_municipios WHERE ID_DEPARTAMENTO=P_ID_DEPARTAMENTO AND ACTIVO=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='No puede inactivar el departamento mientras tenga municipios activos.'; END IF;
    IF P_ID_DEPARTAMENTO IS NULL THEN
      INSERT INTO bbf_departamentos(CODIGO_DANE,NOMBRE,ACTIVO) VALUES(P_CODIGO_DANE,P_NOMBRE,IFNULL(P_ACTIVO,1)); SET P_ID_DEPARTAMENTO=LAST_INSERT_ID();
    ELSE
      IF NOT EXISTS(SELECT 1 FROM bbf_departamentos WHERE ID_DEPARTAMENTO=P_ID_DEPARTAMENTO) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El departamento no existe.'; END IF;
      UPDATE bbf_departamentos SET CODIGO_DANE=P_CODIGO_DANE,NOMBRE=P_NOMBRE,ACTIVO=IFNULL(P_ACTIVO,1),UPDATED_AT=CURRENT_TIMESTAMP WHERE ID_DEPARTAMENTO=P_ID_DEPARTAMENTO;
    END IF;
    SELECT ID_DEPARTAMENTO,CODIGO_DANE,NOMBRE,ACTIVO FROM bbf_departamentos WHERE ID_DEPARTAMENTO=P_ID_DEPARTAMENTO;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
