CREATE  PROCEDURE `SP_BBF_PARAM_DOCUMENTOS_LABORALES_LISTAR`(
    IN P_INCLUIR_INACTIVOS TINYINT
)
BEGIN

    SELECT
        `ID_TIPO_DOCUMENTO_LABORAL`,
        `NOMBRE`,
        `DESCRIPCION`,
        `OBLIGATORIO`,
        `REQUIERE_VENCIMIENTO`,
        `APLICA_ASPIRANTE`,
        `APLICA_CONTRATACION`,
        `APLICA_RETIRO`,
        `ACTIVO`,
        `CREATED_AT`,
        `UPDATED_AT`
    FROM `bbf_tipos_documento_laboral`
    WHERE
        IFNULL(P_INCLUIR_INACTIVOS, 0) = 1
        OR `ACTIVO` = 1
    ORDER BY
        `OBLIGATORIO` DESC,
        `NOMBRE`;

END ;;
DELIMITER ;
