/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_PARAM_DOCUMENTO_LABORAL_GUARDAR`(
    IN P_ID_TIPO_DOCUMENTO_LABORAL INT,
    IN P_NOMBRE VARCHAR(150),
    IN P_DESCRIPCION VARCHAR(500),
    IN P_OBLIGATORIO TINYINT,
    IN P_REQUIERE_VENCIMIENTO TINYINT,
    IN P_APLICA_ASPIRANTE TINYINT,
    IN P_APLICA_CONTRATACION TINYINT,
    IN P_APLICA_RETIRO TINYINT,
    IN P_ACTIVO TINYINT
)
BEGIN

    DECLARE V_ID INT;

    IF NULLIF(TRIM(P_NOMBRE), '') IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El nombre del documento laboral es obligatorio.';
    END IF;

    IF IFNULL(P_ID_TIPO_DOCUMENTO_LABORAL, 0) = 0 THEN

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_tipos_documento_laboral`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe un documento laboral con ese nombre.';
        END IF;

        INSERT INTO `bbf_tipos_documento_laboral`
        (
            `NOMBRE`,
            `DESCRIPCION`,
            `OBLIGATORIO`,
            `REQUIERE_VENCIMIENTO`,
            `APLICA_ASPIRANTE`,
            `APLICA_CONTRATACION`,
            `APLICA_RETIRO`,
            `ACTIVO`
        )
        VALUES
        (
            TRIM(P_NOMBRE),
            NULLIF(TRIM(P_DESCRIPCION), ''),
            IFNULL(P_OBLIGATORIO, 0),
            IFNULL(P_REQUIERE_VENCIMIENTO, 0),
            IFNULL(P_APLICA_ASPIRANTE, 0),
            IFNULL(P_APLICA_CONTRATACION, 1),
            IFNULL(P_APLICA_RETIRO, 0),
            IFNULL(P_ACTIVO, 1)
        );

        SET V_ID = LAST_INSERT_ID();

    ELSE

        IF NOT EXISTS
        (
            SELECT 1
            FROM `bbf_tipos_documento_laboral`
            WHERE `ID_TIPO_DOCUMENTO_LABORAL` =
                  P_ID_TIPO_DOCUMENTO_LABORAL
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'El documento laboral indicado no existe.';
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_tipos_documento_laboral`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
              AND `ID_TIPO_DOCUMENTO_LABORAL` <>
                  P_ID_TIPO_DOCUMENTO_LABORAL
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe otro documento laboral con ese nombre.';
        END IF;

        UPDATE `bbf_tipos_documento_laboral`
        SET
            `NOMBRE` = TRIM(P_NOMBRE),
            `DESCRIPCION` =
                NULLIF(TRIM(P_DESCRIPCION), ''),
            `OBLIGATORIO` =
                IFNULL(P_OBLIGATORIO, `OBLIGATORIO`),
            `REQUIERE_VENCIMIENTO` =
                IFNULL(
                    P_REQUIERE_VENCIMIENTO,
                    `REQUIERE_VENCIMIENTO`
                ),
            `APLICA_ASPIRANTE` =
                IFNULL(
                    P_APLICA_ASPIRANTE,
                    `APLICA_ASPIRANTE`
                ),
            `APLICA_CONTRATACION` =
                IFNULL(
                    P_APLICA_CONTRATACION,
                    `APLICA_CONTRATACION`
                ),
            `APLICA_RETIRO` =
                IFNULL(
                    P_APLICA_RETIRO,
                    `APLICA_RETIRO`
                ),
            `ACTIVO` =
                IFNULL(P_ACTIVO, `ACTIVO`),
            `UPDATED_AT` =
                CURRENT_TIMESTAMP
        WHERE `ID_TIPO_DOCUMENTO_LABORAL` =
              P_ID_TIPO_DOCUMENTO_LABORAL;

        SET V_ID =
            P_ID_TIPO_DOCUMENTO_LABORAL;

    END IF;

    SELECT *
    FROM `bbf_tipos_documento_laboral`
    WHERE `ID_TIPO_DOCUMENTO_LABORAL` = V_ID;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_PARAM_DOTACION_ARTICULOS_LISTAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_PARAM_DOTACION_ARTICULOS_LISTAR`(
    IN P_INCLUIR_INACTIVOS TINYINT
)
BEGIN

    SELECT
        DA.`ID_DOTACION_ARTICULO`,
        DA.`CODIGO`,
        DA.`NOMBRE`,
        DA.`DESCRIPCION`,
        DA.`GENERO`,
        DA.`UNIDAD_MEDIDA`,

        -- Campos técnicos.
        DA.`ID_TIPO_DOTACION`,
        TD.`REQUIERE_TALLA`,

        DA.`ACTIVO`,
        DA.`CREATED_AT`,
        DA.`UPDATED_AT`

    FROM `bbf_dotacion_articulos` DA

    INNER JOIN `bbf_tipos_dotacion` TD
        ON TD.`ID_TIPO_DOTACION` =
           DA.`ID_TIPO_DOTACION`

    WHERE DA.`ES_LEGACY` = 0
      AND
      (
          IFNULL(P_INCLUIR_INACTIVOS, 0) = 1
          OR DA.`ACTIVO` = 1
      )

    ORDER BY DA.`NOMBRE`;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_PARAM_DOTACION_ARTICULO_GUARDAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_PARAM_DOTACION_ARTICULO_GUARDAR`(
    IN P_ID_DOTACION_ARTICULO INT,
    IN P_CODIGO VARCHAR(50),
    IN P_ID_TIPO_DOTACION INT,
    IN P_NOMBRE VARCHAR(200),
    IN P_DESCRIPCION VARCHAR(500),
    IN P_GENERO VARCHAR(20),
    IN P_UNIDAD_MEDIDA VARCHAR(20),
    IN P_ACTIVO TINYINT
)
BEGIN

    DECLARE V_ID INT;
    DECLARE V_CODIGO VARCHAR(50);
    DECLARE V_GENERO VARCHAR(20);
    DECLARE V_UNIDAD VARCHAR(20);
    DECLARE V_TIPO_ACTUAL INT;

    SET V_CODIGO =
        UPPER(TRIM(P_CODIGO));

    SET V_GENERO =
        UPPER(TRIM(P_GENERO));

    SET V_UNIDAD =
        UPPER(TRIM(P_UNIDAD_MEDIDA));

    IF NULLIF(V_CODIGO, '') IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El código del artículo es obligatorio.';
    END IF;

    IF NULLIF(TRIM(P_NOMBRE), '') IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El nombre del artículo es obligatorio.';
    END IF;

    IF V_GENERO NOT IN
    (
        'HOMBRE',
        'MUJER',
        'UNISEX',
        'NO_APLICA'
    )
    THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Género de artículo no válido.';
    END IF;

    IF V_UNIDAD NOT IN
    (
        'UNIDAD',
        'PAR',
        'JUEGO'
    )
    THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Unidad de medida no válida.';
    END IF;

    IF NOT EXISTS
    (
        SELECT 1
        FROM `bbf_tipos_dotacion`
        WHERE `ID_TIPO_DOTACION` =
              P_ID_TIPO_DOTACION
    )
    THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'La familia técnica de talla no existe.';
    END IF;

    IF IFNULL(P_ID_DOTACION_ARTICULO, 0) = 0 THEN

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_dotacion_articulos`
            WHERE `CODIGO` = V_CODIGO
        )
        THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe un artículo con ese código.';
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_dotacion_articulos`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
        )
        THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe un artículo con ese nombre.';
        END IF;

        INSERT INTO `bbf_dotacion_articulos`
        (
            `CODIGO`,
            `ID_TIPO_DOTACION`,
            `NOMBRE`,
            `DESCRIPCION`,
            `GENERO`,
            `UNIDAD_MEDIDA`,
            `ES_LEGACY`,
            `ACTIVO`
        )
        VALUES
        (
            V_CODIGO,
            P_ID_TIPO_DOTACION,
            TRIM(P_NOMBRE),
            NULLIF(TRIM(P_DESCRIPCION), ''),
            V_GENERO,
            V_UNIDAD,
            0,
            IFNULL(P_ACTIVO, 1)
        );

        SET V_ID = LAST_INSERT_ID();

    ELSE

        SELECT
            `ID_TIPO_DOTACION`
        INTO
            V_TIPO_ACTUAL
        FROM `bbf_dotacion_articulos`
        WHERE `ID_DOTACION_ARTICULO` =
              P_ID_DOTACION_ARTICULO
          AND `ES_LEGACY` = 0;

        IF V_TIPO_ACTUAL IS NULL THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'El artículo indicado no existe o es histórico.';
        END IF;

        -- La familia técnica no debe cambiarse una vez creado
        -- porque tallas, entregas e histórico dependen de ella.

        IF V_TIPO_ACTUAL <> P_ID_TIPO_DOTACION THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'No se puede cambiar la familia técnica de un artículo existente.';
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_dotacion_articulos`
            WHERE `CODIGO` = V_CODIGO
              AND `ID_DOTACION_ARTICULO` <>
                  P_ID_DOTACION_ARTICULO
        )
        THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe otro artículo con ese código.';
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_dotacion_articulos`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
              AND `ID_DOTACION_ARTICULO` <>
                  P_ID_DOTACION_ARTICULO
        )
        THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe otro artículo con ese nombre.';
        END IF;

        UPDATE `bbf_dotacion_articulos`
        SET
            `CODIGO` = V_CODIGO,
            `NOMBRE` = TRIM(P_NOMBRE),
            `DESCRIPCION` =
                NULLIF(TRIM(P_DESCRIPCION), ''),
            `GENERO` = V_GENERO,
            `UNIDAD_MEDIDA` = V_UNIDAD,
            `ACTIVO` =
                IFNULL(P_ACTIVO, `ACTIVO`),
            `UPDATED_AT` =
                CURRENT_TIMESTAMP
        WHERE `ID_DOTACION_ARTICULO` =
              P_ID_DOTACION_ARTICULO
          AND `ES_LEGACY` = 0;

        SET V_ID = P_ID_DOTACION_ARTICULO;

    END IF;

    SELECT
        DA.`ID_DOTACION_ARTICULO`,
        DA.`CODIGO`,
        DA.`NOMBRE`,
        DA.`DESCRIPCION`,
        DA.`GENERO`,
        DA.`UNIDAD_MEDIDA`,
        DA.`ID_TIPO_DOTACION`,
        TD.`REQUIERE_TALLA`,
        DA.`ACTIVO`
    FROM `bbf_dotacion_articulos` DA
    INNER JOIN `bbf_tipos_dotacion` TD
        ON TD.`ID_TIPO_DOTACION` =
           DA.`ID_TIPO_DOTACION`
    WHERE DA.`ID_DOTACION_ARTICULO` = V_ID;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_PARAM_MUNICIPIOS_LISTAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_PARAM_MUNICIPIOS_LISTAR`(IN P_ID_DEPARTAMENTO INT, IN P_INCLUIR_INACTIVOS TINYINT)
BEGIN
 SELECT M.ID_MUNICIPIO,M.ID_DEPARTAMENTO,D.CODIGO_DANE CODIGO_DEPARTAMENTO,D.NOMBRE DEPARTAMENTO,M.CODIGO_DANE,M.NOMBRE,M.ACTIVO
 FROM bbf_municipios M INNER JOIN bbf_departamentos D ON D.ID_DEPARTAMENTO=M.ID_DEPARTAMENTO
 WHERE (P_ID_DEPARTAMENTO IS NULL OR P_ID_DEPARTAMENTO=0 OR M.ID_DEPARTAMENTO=P_ID_DEPARTAMENTO)
   AND (IFNULL(P_INCLUIR_INACTIVOS,0)=1 OR M.ACTIVO=1)
 ORDER BY D.NOMBRE,M.NOMBRE;
END ;;
DELIMITER ;
