CREATE  PROCEDURE `SP_BBF_PARAM_MUNICIPIO_GUARDAR`(
 IN P_ID_MUNICIPIO INT, IN P_ID_DEPARTAMENTO INT, IN P_CODIGO_DANE VARCHAR(5), IN P_NOMBRE VARCHAR(150), IN P_ACTIVO TINYINT)
BEGIN
 DECLARE V_CODIGO_DEP VARCHAR(2);
 SET P_CODIGO_DANE=TRIM(P_CODIGO_DANE); SET P_NOMBRE=TRIM(P_NOMBRE);
 SELECT CODIGO_DANE INTO V_CODIGO_DEP FROM bbf_departamentos WHERE ID_DEPARTAMENTO=P_ID_DEPARTAMENTO AND (ACTIVO=1 OR IFNULL(P_ACTIVO,1)=0) LIMIT 1;
 IF V_CODIGO_DEP IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El departamento no existe o esta inactivo.'; END IF;
 IF P_CODIGO_DANE NOT REGEXP '^[0-9]{5}$' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El codigo DANE del municipio debe contener exactamente 5 digitos.'; END IF;
 IF LEFT(P_CODIGO_DANE,2)<>V_CODIGO_DEP THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El codigo DANE del municipio no corresponde al departamento.'; END IF;
 IF P_NOMBRE IS NULL OR P_NOMBRE='' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El nombre del municipio es obligatorio.'; END IF;
 IF EXISTS(SELECT 1 FROM bbf_municipios WHERE CODIGO_DANE=P_CODIGO_DANE AND (P_ID_MUNICIPIO IS NULL OR ID_MUNICIPIO<>P_ID_MUNICIPIO)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Ya existe un municipio con ese codigo DANE.'; END IF;
 IF EXISTS(SELECT 1 FROM bbf_municipios WHERE ID_DEPARTAMENTO=P_ID_DEPARTAMENTO AND UPPER(NOMBRE)=UPPER(P_NOMBRE) AND (P_ID_MUNICIPIO IS NULL OR ID_MUNICIPIO<>P_ID_MUNICIPIO)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Ya existe ese municipio en el departamento.'; END IF;
 IF P_ID_MUNICIPIO IS NULL THEN INSERT INTO bbf_municipios(ID_DEPARTAMENTO,CODIGO_DANE,NOMBRE,ACTIVO) VALUES(P_ID_DEPARTAMENTO,P_CODIGO_DANE,P_NOMBRE,IFNULL(P_ACTIVO,1)); SET P_ID_MUNICIPIO=LAST_INSERT_ID();
 ELSE
  IF NOT EXISTS(SELECT 1 FROM bbf_municipios WHERE ID_MUNICIPIO=P_ID_MUNICIPIO) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El municipio no existe.'; END IF;
  UPDATE bbf_municipios SET ID_DEPARTAMENTO=P_ID_DEPARTAMENTO,CODIGO_DANE=P_CODIGO_DANE,NOMBRE=P_NOMBRE,ACTIVO=IFNULL(P_ACTIVO,1),UPDATED_AT=CURRENT_TIMESTAMP WHERE ID_MUNICIPIO=P_ID_MUNICIPIO;
 END IF;
 SELECT ID_MUNICIPIO,ID_DEPARTAMENTO,CODIGO_DANE,NOMBRE,ACTIVO FROM bbf_municipios WHERE ID_MUNICIPIO=P_ID_MUNICIPIO;
END ;;
DELIMITER ;
