CREATE  PROCEDURE `SP_BBF_PARAM_SEGURIDAD_SOCIAL_GUARDAR`(
    IN P_ID_ENTIDAD INT,
    IN P_TIPO_ENTIDAD VARCHAR(30),
    IN P_NOMBRE VARCHAR(150),
    IN P_NIT VARCHAR(50),
    IN P_ACTIVO TINYINT
)
BEGIN

    DECLARE V_ID INT;
    DECLARE V_TIPO VARCHAR(30);

    SET V_TIPO =
        UPPER(TRIM(P_TIPO_ENTIDAD));

    IF V_TIPO NOT IN
    (
        'EPS',
        'ARL',
        'PENSION',
        'CESANTIAS',
        'CAJA_COMPENSACION'
    )
    THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Tipo de entidad de seguridad social no válido.';
    END IF;

    IF NULLIF(TRIM(P_NOMBRE), '') IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El nombre de la entidad es obligatorio.';
    END IF;

    IF IFNULL(P_ID_ENTIDAD, 0) = 0 THEN

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_entidades_seguridad_social`
            WHERE `TIPO_ENTIDAD` = V_TIPO
              AND UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe esa entidad para el tipo seleccionado.';
        END IF;

        INSERT INTO `bbf_entidades_seguridad_social`
        (
            `TIPO_ENTIDAD`,
            `NOMBRE`,
            `NIT`,
            `ACTIVO`
        )
        VALUES
        (
            V_TIPO,
            TRIM(P_NOMBRE),
            NULLIF(TRIM(P_NIT), ''),
            IFNULL(P_ACTIVO, 1)
        );

        SET V_ID = LAST_INSERT_ID();

    ELSE

        IF NOT EXISTS
        (
            SELECT 1
            FROM `bbf_entidades_seguridad_social`
            WHERE `ID_ENTIDAD_SEGURIDAD_SOCIAL` =
                  P_ID_ENTIDAD
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'La entidad indicada no existe.';
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_entidades_seguridad_social`
            WHERE `TIPO_ENTIDAD` = V_TIPO
              AND UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
              AND `ID_ENTIDAD_SEGURIDAD_SOCIAL` <>
                  P_ID_ENTIDAD
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe otra entidad con ese nombre.';
        END IF;

        UPDATE `bbf_entidades_seguridad_social`
        SET
            `TIPO_ENTIDAD` = V_TIPO,
            `NOMBRE` = TRIM(P_NOMBRE),
            `NIT` =
                NULLIF(TRIM(P_NIT), ''),
            `ACTIVO` =
                IFNULL(P_ACTIVO, `ACTIVO`),
            `UPDATED_AT` =
                CURRENT_TIMESTAMP
        WHERE `ID_ENTIDAD_SEGURIDAD_SOCIAL` =
              P_ID_ENTIDAD;

        SET V_ID = P_ID_ENTIDAD;

    END IF;

    SELECT *
    FROM `bbf_entidades_seguridad_social`
    WHERE `ID_ENTIDAD_SEGURIDAD_SOCIAL` = V_ID;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
