CREATE  PROCEDURE `SP_BBF_PARAM_SEGURIDAD_SOCIAL_LISTAR`(
    IN P_TIPO_ENTIDAD VARCHAR(30),
    IN P_INCLUIR_INACTIVOS TINYINT
)
BEGIN

    DECLARE V_TIPO VARCHAR(30);

    SET V_TIPO =
        NULLIF(
            UPPER(TRIM(P_TIPO_ENTIDAD)),
            ''
        );

    IF V_TIPO IS NOT NULL
       AND V_TIPO NOT IN
       (
           'EPS',
           'ARL',
           'PENSION',
           'CESANTIAS',
           'CAJA_COMPENSACION'
       )
    THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Tipo de entidad de seguridad social no válido.';

    END IF;

    SELECT
        `ID_ENTIDAD_SEGURIDAD_SOCIAL`,
        `TIPO_ENTIDAD`,
        `NOMBRE`,
        `NIT`,
        `ACTIVO`,
        `CREATED_AT`,
        `UPDATED_AT`
    FROM `bbf_entidades_seguridad_social`
    WHERE
        (
            V_TIPO IS NULL
            OR `TIPO_ENTIDAD` = V_TIPO
        )
        AND
        (
            IFNULL(P_INCLUIR_INACTIVOS, 0) = 1
            OR `ACTIVO` = 1
        )
    ORDER BY
        `TIPO_ENTIDAD`,
        `NOMBRE`;

END ;;
DELIMITER ;
