CREATE  PROCEDURE `SP_BBF_PARAM_SISTEMA_GUARDAR`(
    IN P_ID_PARAMETRO INT,
    IN P_CODIGO VARCHAR(100),
    IN P_NOMBRE VARCHAR(150),
    IN P_GRUPO VARCHAR(100),
    IN P_DESCRIPCION VARCHAR(500),
    IN P_TIPO_DATO VARCHAR(20),
    IN P_VALOR LONGTEXT,
    IN P_UNIDAD_MEDIDA VARCHAR(50),
    IN P_VIGENCIA_DESDE DATE,
    IN P_VIGENCIA_HASTA DATE,
    IN P_ACTIVO TINYINT,
    IN P_EDITABLE TINYINT,
    IN P_ID_USUARIO INT
)
BEGIN

    DECLARE V_ID INT;
    DECLARE V_CODIGO VARCHAR(100);
    DECLARE V_GRUPO VARCHAR(100);
    DECLARE V_TIPO VARCHAR(20);
    DECLARE V_EDITABLE TINYINT;

    SET V_CODIGO =
        UPPER(TRIM(P_CODIGO));

    SET V_GRUPO =
        UPPER(
            TRIM(
                IFNULL(P_GRUPO, 'GENERAL')
            )
        );

    SET V_TIPO =
        UPPER(TRIM(P_TIPO_DATO));

    IF NULLIF(V_CODIGO, '') IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El código del parámetro es obligatorio.';
    END IF;

    IF NULLIF(TRIM(P_NOMBRE), '') IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El nombre del parámetro es obligatorio.';
    END IF;

    IF P_VALOR IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El valor del parámetro es obligatorio.';
    END IF;

    IF V_TIPO NOT IN
    (
        'TEXTO',
        'NUMERICO',
        'FECHA',
        'BOOLEANO',
        'JSON'
    )
    THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Tipo de dato del parámetro no válido.';
    END IF;

    IF P_VIGENCIA_DESDE IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'La fecha de inicio de vigencia es obligatoria.';
    END IF;

    IF P_VIGENCIA_HASTA IS NOT NULL
       AND P_VIGENCIA_HASTA < P_VIGENCIA_DESDE
    THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'La vigencia final no puede ser anterior a la inicial.';
    END IF;

    IF V_TIPO = 'JSON'
       AND JSON_VALID(P_VALOR) = 0
    THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El valor indicado no contiene un JSON válido.';
    END IF;

    IF IFNULL(P_ID_PARAMETRO, 0) = 0 THEN

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_parametros_sistema`
            WHERE `CODIGO` = V_CODIGO
              AND `VIGENCIA_DESDE` =
                  P_VIGENCIA_DESDE
        )
        THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe este parámetro para la misma fecha de vigencia.';
        END IF;

        INSERT INTO `bbf_parametros_sistema`
        (
            `CODIGO`,
            `NOMBRE`,
            `GRUPO`,
            `DESCRIPCION`,
            `TIPO_DATO`,
            `VALOR`,
            `UNIDAD_MEDIDA`,
            `VIGENCIA_DESDE`,
            `VIGENCIA_HASTA`,
            `ACTIVO`,
            `EDITABLE`,
            `ID_CREADO_POR`
        )
        VALUES
        (
            V_CODIGO,
            TRIM(P_NOMBRE),
            V_GRUPO,
            NULLIF(TRIM(P_DESCRIPCION), ''),
            V_TIPO,
            P_VALOR,
            NULLIF(TRIM(P_UNIDAD_MEDIDA), ''),
            P_VIGENCIA_DESDE,
            P_VIGENCIA_HASTA,
            IFNULL(P_ACTIVO, 1),
            IFNULL(P_EDITABLE, 1),
            P_ID_USUARIO
        );

        SET V_ID = LAST_INSERT_ID();

    ELSE

        SELECT
            `EDITABLE`
        INTO
            V_EDITABLE
        FROM `bbf_parametros_sistema`
        WHERE `ID_PARAMETRO` =
              P_ID_PARAMETRO;

        IF V_EDITABLE IS NULL THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'El parámetro indicado no existe.';
        END IF;

        IF V_EDITABLE = 0 THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Este parámetro no permite modificaciones.';
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_parametros_sistema`
            WHERE `CODIGO` = V_CODIGO
              AND `VIGENCIA_DESDE` =
                  P_VIGENCIA_DESDE
              AND `ID_PARAMETRO` <>
                  P_ID_PARAMETRO
        )
        THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe otro parámetro con el mismo código y vigencia.';
        END IF;

        UPDATE `bbf_parametros_sistema`
        SET
            `CODIGO` = V_CODIGO,
            `NOMBRE` = TRIM(P_NOMBRE),
            `GRUPO` = V_GRUPO,
            `DESCRIPCION` =
                NULLIF(TRIM(P_DESCRIPCION), ''),
            `TIPO_DATO` = V_TIPO,
            `VALOR` = P_VALOR,
            `UNIDAD_MEDIDA` =
                NULLIF(TRIM(P_UNIDAD_MEDIDA), ''),
            `VIGENCIA_DESDE` =
                P_VIGENCIA_DESDE,
            `VIGENCIA_HASTA` =
                P_VIGENCIA_HASTA,
            `ACTIVO` =
                IFNULL(P_ACTIVO, `ACTIVO`),
            `EDITABLE` =
                IFNULL(P_EDITABLE, `EDITABLE`),
            `ID_ACTUALIZADO_POR` =
                P_ID_USUARIO,
            `UPDATED_AT` =
                CURRENT_TIMESTAMP
        WHERE `ID_PARAMETRO` =
              P_ID_PARAMETRO;

        SET V_ID = P_ID_PARAMETRO;

    END IF;

    SELECT
        `ID_PARAMETRO`,
        `CODIGO`,
        `NOMBRE`,
        `GRUPO`,
        `DESCRIPCION`,
        `TIPO_DATO`,
        `VALOR`,
        `UNIDAD_MEDIDA`,
        `VIGENCIA_DESDE`,
        `VIGENCIA_HASTA`,
        `ACTIVO`,
        `EDITABLE`,
        `ID_CREADO_POR`,
        `ID_ACTUALIZADO_POR`,
        `CREATED_AT`,
        `UPDATED_AT`
    FROM `bbf_parametros_sistema`
    WHERE `ID_PARAMETRO` = V_ID;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
