CREATE  PROCEDURE `SP_BBF_PARAM_TIPOS_CONTRATO_GUARDAR`(
    IN P_ID_TIPO_CONTRATO INT,
    IN P_NOMBRE VARCHAR(150),
    IN P_DESCRIPCION TEXT,
    IN P_ACTIVO TINYINT
)
BEGIN

    DECLARE V_ID INT;

    IF NULLIF(TRIM(P_NOMBRE), '') IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El nombre del tipo de contrato es obligatorio.';
    END IF;

    IF IFNULL(P_ID_TIPO_CONTRATO, 0) = 0 THEN

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_tipos_contrato`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe un tipo de contrato con ese nombre.';
        END IF;

        INSERT INTO `bbf_tipos_contrato`
        (
            `NOMBRE`,
            `DESCRIPCION`,
            `ACTIVO`
        )
        VALUES
        (
            TRIM(P_NOMBRE),
            NULLIF(TRIM(P_DESCRIPCION), ''),
            IFNULL(P_ACTIVO, 1)
        );

        SET V_ID = LAST_INSERT_ID();

    ELSE

        IF NOT EXISTS
        (
            SELECT 1
            FROM `bbf_tipos_contrato`
            WHERE `ID_TIPO_CONTRATO` =
                  P_ID_TIPO_CONTRATO
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'El tipo de contrato no existe.';
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_tipos_contrato`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
              AND `ID_TIPO_CONTRATO` <>
                  P_ID_TIPO_CONTRATO
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe otro tipo de contrato con ese nombre.';
        END IF;

        UPDATE `bbf_tipos_contrato`
        SET
            `NOMBRE` = TRIM(P_NOMBRE),
            `DESCRIPCION` =
                NULLIF(TRIM(P_DESCRIPCION), ''),
            `ACTIVO` =
                IFNULL(P_ACTIVO, `ACTIVO`),
            `UPDATED_AT` = CURRENT_TIMESTAMP
        WHERE `ID_TIPO_CONTRATO` =
              P_ID_TIPO_CONTRATO;

        SET V_ID = P_ID_TIPO_CONTRATO;

    END IF;

    SELECT *
    FROM `bbf_tipos_contrato`
    WHERE `ID_TIPO_CONTRATO` = V_ID;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
