CREATE  PROCEDURE `SP_BBF_PARAM_TIPOS_CONTRATO_LISTAR`(
    IN P_INCLUIR_INACTIVOS TINYINT
)
BEGIN

    SELECT
        `ID_TIPO_CONTRATO`,
        `NOMBRE`,
        `DESCRIPCION`,
        `ACTIVO`,
        `CREATED_AT`,
        `UPDATED_AT`
    FROM `bbf_tipos_contrato`
    WHERE
        IFNULL(P_INCLUIR_INACTIVOS, 0) = 1
        OR `ACTIVO` = 1
    ORDER BY `NOMBRE`;

END ;;
DELIMITER ;
