CREATE  PROCEDURE `SP_BBF_PARAM_TIPOS_DOCUMENTO_GUARDAR`(
    IN P_ID_TIPO_DOCUMENTO INT,
    IN P_NOMBRE VARCHAR(80),
    IN P_ACTIVO TINYINT
)
BEGIN

    DECLARE V_ID INT;

    IF NULLIF(TRIM(P_NOMBRE), '') IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El nombre del tipo de documento es obligatorio.';
    END IF;

    IF IFNULL(P_ID_TIPO_DOCUMENTO, 0) = 0 THEN

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_tipos_documento`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe un tipo de documento con ese nombre.';
        END IF;

        INSERT INTO `bbf_tipos_documento`
        (
            `NOMBRE`,
            `ACTIVO`
        )
        VALUES
        (
            TRIM(P_NOMBRE),
            IFNULL(P_ACTIVO, 1)
        );

        SET V_ID = LAST_INSERT_ID();

    ELSE

        IF NOT EXISTS
        (
            SELECT 1
            FROM `bbf_tipos_documento`
            WHERE `ID_TIPO_DOCUMENTO` =
                  P_ID_TIPO_DOCUMENTO
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'El tipo de documento indicado no existe.';
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_tipos_documento`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
              AND `ID_TIPO_DOCUMENTO` <>
                  P_ID_TIPO_DOCUMENTO
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe otro tipo de documento con ese nombre.';
        END IF;

        UPDATE `bbf_tipos_documento`
        SET
            `NOMBRE` = TRIM(P_NOMBRE),
            `ACTIVO` =
                IFNULL(P_ACTIVO, `ACTIVO`),
            `UPDATED_AT` = CURRENT_TIMESTAMP
        WHERE `ID_TIPO_DOCUMENTO` =
              P_ID_TIPO_DOCUMENTO;

        SET V_ID = P_ID_TIPO_DOCUMENTO;

    END IF;

    SELECT *
    FROM `bbf_tipos_documento`
    WHERE `ID_TIPO_DOCUMENTO` = V_ID;

END ;;
DELIMITER ;
