CREATE  PROCEDURE `SP_BBF_PARAM_TIPOS_DOCUMENTO_LISTAR`(
    IN P_INCLUIR_INACTIVOS TINYINT
)
BEGIN

    SELECT
        `ID_TIPO_DOCUMENTO`,
        `NOMBRE`,
        `ACTIVO`,
        `CREATED_AT`,
        `UPDATED_AT`
    FROM `bbf_tipos_documento`
    WHERE
        IFNULL(P_INCLUIR_INACTIVOS, 0) = 1
        OR `ACTIVO` = 1
    ORDER BY `NOMBRE`;

END ;;
