CREATE  PROCEDURE `SP_BBF_PARAM_TIPOS_NOVEDAD_LISTAR`(IN P_INCLUIR_INACTIVOS TINYINT)
BEGIN
    SELECT
        TN.ID_TIPO_NOVEDAD,
        TN.CODIGO,
        TN.NOMBRE,
        TN.DESCRIPCION,
        TN.REQUIERE_FECHA_FIN,
        TN.REQUIERE_SOPORTE,
        TN.ES_INCAPACIDAD,
        TN.ACTIVO,
        COUNT(N.ID_NOVEDAD) AS TOTAL_NOVEDADES,
        SUM(CASE WHEN N.ESTADO IN ('REGISTRADA','VALIDADA') THEN 1 ELSE 0 END) AS NOVEDADES_ACTIVAS,
        TN.CREATED_AT,
        TN.UPDATED_AT
    FROM bbf_tipos_novedad TN
    LEFT JOIN bbf_novedades_empleado N
      ON N.ID_TIPO_NOVEDAD = TN.ID_TIPO_NOVEDAD
    WHERE IFNULL(P_INCLUIR_INACTIVOS, 0) = 1 OR TN.ACTIVO = 1
    GROUP BY
        TN.ID_TIPO_NOVEDAD, TN.CODIGO, TN.NOMBRE, TN.DESCRIPCION,
        TN.REQUIERE_FECHA_FIN, TN.REQUIERE_SOPORTE, TN.ES_INCAPACIDAD,
        TN.ACTIVO, TN.CREATED_AT, TN.UPDATED_AT
    ORDER BY TN.NOMBRE;
END ;;
DELIMITER ;
