CREATE  PROCEDURE `SP_BBF_PARAM_TIPO_EXAMEN_GUARDAR`(
    IN P_ID_TIPO_EXAMEN INT,
    IN P_NOMBRE VARCHAR(120),
    IN P_DESCRIPCION VARCHAR(500),
    IN P_ACTIVO TINYINT
)
BEGIN

    DECLARE V_ID INT;

    IF NULLIF(TRIM(P_NOMBRE), '') IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El nombre del tipo de examen es obligatorio.';
    END IF;

    IF IFNULL(P_ID_TIPO_EXAMEN, 0) = 0 THEN

        IF EXISTS
        (
            SELECT 1
            FROM `bbf_tipos_examen_medico`
            WHERE UPPER(TRIM(`NOMBRE`)) =
                  UPPER(TRIM(P_NOMBRE))
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Ya existe un tipo de examen con ese nombre.';
        END IF;

        INSERT INTO `bbf_tipos_examen_medico`
        (
            `NOMBRE`,
            `DESCRIPCION`,
            `ACTIVO`
        )
        VALUES
        (
            TRIM(P_NOMBRE),
            NULLIF(TRIM(P_DESCRIPCION), ''),
            IFNULL(P_ACTIVO, 1)
        );

        SET V_ID = LAST_INSERT_ID();

    ELSE

        UPDATE `bbf_tipos_examen_medico`
        SET
            `NOMBRE` = TRIM(P_NOMBRE),
            `DESCRIPCION` =
                NULLIF(TRIM(P_DESCRIPCION), ''),
            `ACTIVO` =
                IFNULL(P_ACTIVO, `ACTIVO`),
            `UPDATED_AT` =
                CURRENT_TIMESTAMP
        WHERE `ID_TIPO_EXAMEN_MEDICO` =
              P_ID_TIPO_EXAMEN;

        IF ROW_COUNT() = 0
           AND NOT EXISTS
           (
               SELECT 1
               FROM `bbf_tipos_examen_medico`
               WHERE `ID_TIPO_EXAMEN_MEDICO` =
                     P_ID_TIPO_EXAMEN
           )
        THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'El tipo de examen indicado no existe.';
        END IF;

        SET V_ID = P_ID_TIPO_EXAMEN;

    END IF;

    SELECT *
    FROM `bbf_tipos_examen_medico`
    WHERE `ID_TIPO_EXAMEN_MEDICO` = V_ID;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
