CREATE  PROCEDURE `SP_BBF_PARAM_TIPO_NOVEDAD_GUARDAR`(
    IN P_ID_TIPO_NOVEDAD INT,
    IN P_CODIGO VARCHAR(50),
    IN P_NOMBRE VARCHAR(150),
    IN P_DESCRIPCION VARCHAR(500),
    IN P_REQUIERE_FECHA_FIN TINYINT,
    IN P_REQUIERE_SOPORTE TINYINT,
    IN P_ES_INCAPACIDAD TINYINT,
    IN P_ACTIVO TINYINT
)
BEGIN
    DECLARE V_ID INT DEFAULT NULL;
    DECLARE V_CODIGO_ACTUAL VARCHAR(50) DEFAULT NULL;
    DECLARE V_ES_INCAPACIDAD_ACTUAL TINYINT DEFAULT 0;
    DECLARE V_TOTAL_NOVEDADES INT DEFAULT 0;
    DECLARE V_NOVEDADES_ACTIVAS INT DEFAULT 0;

    IF NULLIF(TRIM(P_NOMBRE), '') IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El nombre del tipo de novedad es obligatorio.';
    END IF;

    IF P_ID_TIPO_NOVEDAD IS NULL OR P_ID_TIPO_NOVEDAD = 0 THEN
        IF NULLIF(TRIM(P_CODIGO), '') IS NULL THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No fue posible generar el codigo del tipo de novedad.';
        END IF;

        IF EXISTS (SELECT 1 FROM bbf_tipos_novedad WHERE CODIGO = UPPER(TRIM(P_CODIGO))) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ya existe un tipo de novedad con ese codigo.';
        END IF;
        IF EXISTS (SELECT 1 FROM bbf_tipos_novedad WHERE UPPER(TRIM(NOMBRE)) = UPPER(TRIM(P_NOMBRE))) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ya existe un tipo de novedad con ese nombre.';
        END IF;

        INSERT INTO bbf_tipos_novedad
            (CODIGO, NOMBRE, DESCRIPCION, REQUIERE_FECHA_FIN, REQUIERE_SOPORTE, ES_INCAPACIDAD, ACTIVO)
        VALUES
            (UPPER(TRIM(P_CODIGO)), TRIM(P_NOMBRE), NULLIF(TRIM(P_DESCRIPCION), ''),
             IFNULL(P_REQUIERE_FECHA_FIN,0), IFNULL(P_REQUIERE_SOPORTE,0),
             IFNULL(P_ES_INCAPACIDAD,0), IFNULL(P_ACTIVO,1));
        SET V_ID = LAST_INSERT_ID();
    ELSE
        SELECT CODIGO, ES_INCAPACIDAD
          INTO V_CODIGO_ACTUAL, V_ES_INCAPACIDAD_ACTUAL
        FROM bbf_tipos_novedad
        WHERE ID_TIPO_NOVEDAD = P_ID_TIPO_NOVEDAD
        LIMIT 1;

        IF V_CODIGO_ACTUAL IS NULL THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El tipo de novedad no existe.';
        END IF;

        SELECT COUNT(*),
               SUM(CASE WHEN ESTADO IN ('REGISTRADA','VALIDADA') THEN 1 ELSE 0 END)
          INTO V_TOTAL_NOVEDADES, V_NOVEDADES_ACTIVAS
        FROM bbf_novedades_empleado
        WHERE ID_TIPO_NOVEDAD = P_ID_TIPO_NOVEDAD;

        IF V_TOTAL_NOVEDADES > 0 AND IFNULL(P_ES_INCAPACIDAD,0) <> V_ES_INCAPACIDAD_ACTUAL THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'No puede cambiarse la naturaleza del tipo porque ya tiene novedades registradas.';
        END IF;

        IF IFNULL(P_ACTIVO,1) = 0 AND V_NOVEDADES_ACTIVAS > 0 THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'No puede inactivarse el tipo mientras tenga novedades registradas o validadas.';
        END IF;

        IF EXISTS (
            SELECT 1 FROM bbf_tipos_novedad
            WHERE UPPER(TRIM(NOMBRE)) = UPPER(TRIM(P_NOMBRE))
              AND ID_TIPO_NOVEDAD <> P_ID_TIPO_NOVEDAD
        ) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ya existe otro tipo de novedad con ese nombre.';
        END IF;

        UPDATE bbf_tipos_novedad
        SET NOMBRE = TRIM(P_NOMBRE),
            DESCRIPCION = NULLIF(TRIM(P_DESCRIPCION), ''),
            REQUIERE_FECHA_FIN = IFNULL(P_REQUIERE_FECHA_FIN,0),
            REQUIERE_SOPORTE = IFNULL(P_REQUIERE_SOPORTE,0),
            ES_INCAPACIDAD = IFNULL(P_ES_INCAPACIDAD,0),
            ACTIVO = IFNULL(P_ACTIVO,1),
            UPDATED_AT = CURRENT_TIMESTAMP
        WHERE ID_TIPO_NOVEDAD = P_ID_TIPO_NOVEDAD;
        SET V_ID = P_ID_TIPO_NOVEDAD;
    END IF;

    SELECT
        TN.ID_TIPO_NOVEDAD, TN.CODIGO, TN.NOMBRE, TN.DESCRIPCION,
        TN.REQUIERE_FECHA_FIN, TN.REQUIERE_SOPORTE, TN.ES_INCAPACIDAD,
        TN.ACTIVO,
        (SELECT COUNT(*) FROM bbf_novedades_empleado N WHERE N.ID_TIPO_NOVEDAD=TN.ID_TIPO_NOVEDAD) TOTAL_NOVEDADES,
        TN.CREATED_AT, TN.UPDATED_AT
    FROM bbf_tipos_novedad TN
    WHERE TN.ID_TIPO_NOVEDAD = V_ID;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_PASSWORD_RESET_CREAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_unicode_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
