CREATE  PROCEDURE `SP_BBF_PERMISOS_LISTAR`(
    IN P_SOLO_ACTIVOS TINYINT,
    IN P_MODULO VARCHAR(100)
)
BEGIN
    SELECT
        ID_PERMISO,
        CODIGO,
        NOMBRE,
        DESCRIPCION,
        MODULO,
        ACTIVO,
        CREATED_AT,
        UPDATED_AT
    FROM bbf_permisos
    WHERE
        (P_SOLO_ACTIVOS = 0 OR ACTIVO = 1)
        AND (P_MODULO IS NULL OR P_MODULO = '' OR MODULO = P_MODULO)
    ORDER BY MODULO ASC, CODIGO ASC;
END ;;
DELIMITER ;
