/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_RETIROS_ACTIVIDAD_ACTUALIZAR`(IN P_ID_RETIRO INT,IN P_CODIGO_ACTIVIDAD VARCHAR(60),IN P_ESTADO VARCHAR(20),IN P_OBSERVACIONES VARCHAR(1000),IN P_ID_USUARIO INT)
BEGIN
    DECLARE V_REQUIERE_DOCUMENTO TINYINT DEFAULT 0;
    DECLARE V_CANTIDAD_DOCUMENTOS INT DEFAULT 0;
    DECLARE V_NOMBRE_TIPO_DOCUMENTO VARCHAR(150) DEFAULT NULL;
    DECLARE V_DOCUMENTOS_CARGADOS INT DEFAULT 0;
    IF P_ESTADO NOT IN('PENDIENTE','EN_PROCESO','COMPLETADA','NO_APLICA') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Estado de actividad no valido.'; END IF;
    IF NOT EXISTS(SELECT 1 FROM bbf_retiros_empleado WHERE ID_RETIRO=P_ID_RETIRO AND ESTADO IN('BORRADOR','EN_PROCESO')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El retiro no esta disponible para modificacion.'; END IF;
    SELECT REQUIERE_DOCUMENTO,CANTIDAD_DOCUMENTOS,NOMBRE_TIPO_DOCUMENTO
      INTO V_REQUIERE_DOCUMENTO,V_CANTIDAD_DOCUMENTOS,V_NOMBRE_TIPO_DOCUMENTO
    FROM bbf_retiro_tipos_actividad WHERE CODIGO=P_CODIGO_ACTIVIDAD AND ACTIVO=1 LIMIT 1;
    IF P_ESTADO='COMPLETADA' AND V_REQUIERE_DOCUMENTO=1 THEN
        SELECT CASE WHEN P_CODIGO_ACTIVIDAD='PLANILLAS_SEGURIDAD_SOCIAL'
                    THEN COUNT(DISTINCT D.PERIODO_DOCUMENTO) ELSE COUNT(*) END
          INTO V_DOCUMENTOS_CARGADOS
        FROM bbf_empleado_documentos D
        JOIN bbf_tipos_documento_laboral TD ON TD.ID_TIPO_DOCUMENTO_LABORAL=D.ID_TIPO_DOCUMENTO_LABORAL
        WHERE D.ID_RETIRO=P_ID_RETIRO AND D.ELIMINADO=0 AND TD.NOMBRE=V_NOMBRE_TIPO_DOCUMENTO
          AND (P_CODIGO_ACTIVIDAD<>'PLANILLAS_SEGURIDAD_SOCIAL' OR D.PERIODO_DOCUMENTO REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])$');
        IF V_DOCUMENTOS_CARGADOS<V_CANTIDAD_DOCUMENTOS THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='No se puede completar la actividad: faltan documentos requeridos o periodos validos.';
        END IF;
    END IF;
    UPDATE bbf_retiro_actividades A JOIN bbf_retiro_tipos_actividad T ON T.ID_TIPO_ACTIVIDAD_RETIRO=A.ID_TIPO_ACTIVIDAD_RETIRO
    SET A.ESTADO=P_ESTADO,A.FECHA_CUMPLIMIENTO=CASE WHEN P_ESTADO='COMPLETADA' THEN CURRENT_TIMESTAMP ELSE NULL END,
        A.OBSERVACIONES=NULLIF(TRIM(P_OBSERVACIONES),''),A.ID_RESPONSABLE=P_ID_USUARIO,A.UPDATED_AT=CURRENT_TIMESTAMP
    WHERE A.ID_RETIRO=P_ID_RETIRO AND T.CODIGO=P_CODIGO_ACTIVIDAD;
    IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='La actividad indicada no existe en el retiro.'; END IF;
    SELECT A.*,T.CODIGO,T.NOMBRE FROM bbf_retiro_actividades A JOIN bbf_retiro_tipos_actividad T ON T.ID_TIPO_ACTIVIDAD_RETIRO=A.ID_TIPO_ACTIVIDAD_RETIRO WHERE A.ID_RETIRO=P_ID_RETIRO AND T.CODIGO=P_CODIGO_ACTIVIDAD;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
