DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_RETIROS_CANCELAR`(IN P_ID_RETIRO INT,IN P_ID_USUARIO INT,IN P_MOTIVO VARCHAR(500))
BEGIN
    DECLARE V_ID_EMPLEADO INT;
    SELECT ID_EMPLEADO INTO V_ID_EMPLEADO FROM bbf_retiros_empleado WHERE ID_RETIRO=P_ID_RETIRO AND ESTADO IN('BORRADOR','EN_PROCESO') LIMIT 1;
    IF V_ID_EMPLEADO IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El proceso no existe o no se puede cancelar.'; END IF;
    IF NULLIF(TRIM(P_MOTIVO),'') IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El motivo de cancelacion es obligatorio.'; END IF;
    START TRANSACTION;
    UPDATE bbf_retiros_empleado SET ESTADO='CANCELADO',ID_CANCELADO_POR=P_ID_USUARIO,FECHA_CANCELACION=CURRENT_TIMESTAMP,MOTIVO_CANCELACION=TRIM(P_MOTIVO),UPDATED_AT=CURRENT_TIMESTAMP WHERE ID_RETIRO=P_ID_RETIRO;
    UPDATE bbf_empleados SET ESTADO_EMPLEADO='ACTIVO',FECHA_RETIRO=NULL,UPDATED_AT=CURRENT_TIMESTAMP WHERE ID_EMPLEADO=V_ID_EMPLEADO AND ESTADO_EMPLEADO='EN_PROCESO_RETIRO';
    COMMIT;
    SELECT ID_RETIRO,ESTADO,FECHA_CANCELACION,MOTIVO_CANCELACION FROM bbf_retiros_empleado WHERE ID_RETIRO=P_ID_RETIRO;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
