DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_RETIROS_CREAR`(
    IN P_ID_EMPLEADO INT, IN P_ID_EMPLEADO_CONTRATO INT, IN P_ID_MOTIVO_RETIRO INT,
    IN P_FECHA_INICIO_PROCESO DATE, IN P_FECHA_RETIRO DATE, IN P_DETALLE_MOTIVO VARCHAR(1000),
    IN P_OBSERVACIONES TEXT, IN P_ID_USUARIO INT
)
BEGIN
    DECLARE V_ID_RETIRO INT;
    DECLARE V_REQUIERE_RENUNCIA TINYINT DEFAULT NULL;

    IF NOT EXISTS(SELECT 1 FROM bbf_empleados WHERE ID_EMPLEADO=P_ID_EMPLEADO AND ELIMINADO=0 AND ESTADO_EMPLEADO<>'RETIRADO') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El empleado no existe o ya se encuentra retirado.';
    END IF;
    IF EXISTS(SELECT 1 FROM bbf_retiros_empleado WHERE ID_EMPLEADO=P_ID_EMPLEADO AND ESTADO IN('BORRADOR','EN_PROCESO')) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El empleado ya tiene un proceso de retiro activo.';
    END IF;
    SELECT REQUIERE_RENUNCIA INTO V_REQUIERE_RENUNCIA FROM bbf_motivos_retiro WHERE ID_MOTIVO_RETIRO=P_ID_MOTIVO_RETIRO AND ACTIVO=1 LIMIT 1;
    IF V_REQUIERE_RENUNCIA IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El motivo de retiro no existe o esta inactivo.'; END IF;
    IF P_FECHA_RETIRO IS NULL OR P_FECHA_INICIO_PROCESO IS NULL OR P_FECHA_RETIRO<P_FECHA_INICIO_PROCESO THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Las fechas del proceso de retiro no son validas.';
    END IF;
    IF P_ID_EMPLEADO_CONTRATO IS NOT NULL AND NOT EXISTS(SELECT 1 FROM bbf_empleado_contratos WHERE ID_EMPLEADO_CONTRATO=P_ID_EMPLEADO_CONTRATO AND ID_EMPLEADO=P_ID_EMPLEADO AND ELIMINADO=0) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El contrato no pertenece al empleado.';
    END IF;

    START TRANSACTION;
    INSERT INTO bbf_retiros_empleado(ID_EMPLEADO,ID_EMPLEADO_CONTRATO,ID_MOTIVO_RETIRO,FECHA_INICIO_PROCESO,FECHA_RETIRO,DETALLE_MOTIVO,ESTADO,OBSERVACIONES,ID_REGISTRADO_POR)
    VALUES(P_ID_EMPLEADO,P_ID_EMPLEADO_CONTRATO,P_ID_MOTIVO_RETIRO,P_FECHA_INICIO_PROCESO,P_FECHA_RETIRO,NULLIF(TRIM(P_DETALLE_MOTIVO),''),'EN_PROCESO',NULLIF(TRIM(P_OBSERVACIONES),''),P_ID_USUARIO);
    SET V_ID_RETIRO=LAST_INSERT_ID();

    INSERT INTO bbf_retiro_actividades(ID_RETIRO,ID_TIPO_ACTIVIDAD_RETIRO,ESTADO)
    SELECT V_ID_RETIRO,ID_TIPO_ACTIVIDAD_RETIRO,CASE WHEN SOLO_SI_RENUNCIA=1 AND V_REQUIERE_RENUNCIA=0 THEN 'NO_APLICA' ELSE 'PENDIENTE' END
    FROM bbf_retiro_tipos_actividad WHERE ACTIVO=1;

    UPDATE bbf_empleados SET ESTADO_EMPLEADO='EN_PROCESO_RETIRO',FECHA_RETIRO=P_FECHA_RETIRO,UPDATED_AT=CURRENT_TIMESTAMP WHERE ID_EMPLEADO=P_ID_EMPLEADO;
    COMMIT;
    SELECT V_ID_RETIRO AS ID_RETIRO;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
