DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_RETIROS_ENTREVISTA_GUARDAR`(
 IN P_ID_RETIRO INT,IN P_FECHA_ENTREVISTA DATE,IN P_ID_ENTREVISTADOR INT,IN P_MOTIVO_EXPRESADO TEXT,
 IN P_ASPECTOS_POSITIVOS TEXT,IN P_ASPECTOS_POR_MEJORAR TEXT,IN P_AMBIENTE_LABORAL TEXT,
 IN P_RELACION_LIDERAZGO TEXT,IN P_REMUNERACION_BENEFICIOS TEXT,IN P_RECOMENDARIA_EMPRESA TINYINT,
 IN P_ELEGIBLE_RECONTRATACION TINYINT,IN P_CONCLUSIONES TEXT)
BEGIN
    IF NOT EXISTS(SELECT 1 FROM bbf_retiros_empleado WHERE ID_RETIRO=P_ID_RETIRO AND ESTADO IN('BORRADOR','EN_PROCESO')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El retiro no esta disponible para entrevista.'; END IF;
    INSERT INTO bbf_retiro_entrevistas(ID_RETIRO,FECHA_ENTREVISTA,ID_ENTREVISTADOR,MOTIVO_EXPRESADO,ASPECTOS_POSITIVOS,ASPECTOS_POR_MEJORAR,AMBIENTE_LABORAL,RELACION_LIDERAZGO,REMUNERACION_BENEFICIOS,RECOMENDARIA_EMPRESA,ELEGIBLE_RECONTRATACION,CONCLUSIONES)
    VALUES(P_ID_RETIRO,P_FECHA_ENTREVISTA,P_ID_ENTREVISTADOR,P_MOTIVO_EXPRESADO,P_ASPECTOS_POSITIVOS,P_ASPECTOS_POR_MEJORAR,P_AMBIENTE_LABORAL,P_RELACION_LIDERAZGO,P_REMUNERACION_BENEFICIOS,P_RECOMENDARIA_EMPRESA,P_ELEGIBLE_RECONTRATACION,P_CONCLUSIONES)
    ON DUPLICATE KEY UPDATE FECHA_ENTREVISTA=VALUES(FECHA_ENTREVISTA),ID_ENTREVISTADOR=VALUES(ID_ENTREVISTADOR),MOTIVO_EXPRESADO=VALUES(MOTIVO_EXPRESADO),ASPECTOS_POSITIVOS=VALUES(ASPECTOS_POSITIVOS),ASPECTOS_POR_MEJORAR=VALUES(ASPECTOS_POR_MEJORAR),AMBIENTE_LABORAL=VALUES(AMBIENTE_LABORAL),RELACION_LIDERAZGO=VALUES(RELACION_LIDERAZGO),REMUNERACION_BENEFICIOS=VALUES(REMUNERACION_BENEFICIOS),RECOMENDARIA_EMPRESA=VALUES(RECOMENDARIA_EMPRESA),ELEGIBLE_RECONTRATACION=VALUES(ELEGIBLE_RECONTRATACION),CONCLUSIONES=VALUES(CONCLUSIONES),UPDATED_AT=CURRENT_TIMESTAMP;
    UPDATE bbf_retiro_actividades A JOIN bbf_retiro_tipos_actividad T ON T.ID_TIPO_ACTIVIDAD_RETIRO=A.ID_TIPO_ACTIVIDAD_RETIRO SET A.ESTADO='COMPLETADA',A.FECHA_CUMPLIMIENTO=CURRENT_TIMESTAMP,A.ID_RESPONSABLE=P_ID_ENTREVISTADOR WHERE A.ID_RETIRO=P_ID_RETIRO AND T.CODIGO='ENTREVISTA_RETIRO';
    SELECT * FROM bbf_retiro_entrevistas WHERE ID_RETIRO=P_ID_RETIRO;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
