/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_RETIROS_FINALIZAR`(IN P_ID_RETIRO INT,IN P_ID_USUARIO INT,IN P_OBSERVACIONES TEXT)
BEGIN
    DECLARE V_ID_EMPLEADO INT; DECLARE V_ID_CONTRATO INT; DECLARE V_FECHA_RETIRO DATE; DECLARE V_PENDIENTES INT DEFAULT 0; DECLARE V_DOCS_INCOMPLETOS INT DEFAULT 0;
    SELECT ID_EMPLEADO,ID_EMPLEADO_CONTRATO,FECHA_RETIRO INTO V_ID_EMPLEADO,V_ID_CONTRATO,V_FECHA_RETIRO FROM bbf_retiros_empleado WHERE ID_RETIRO=P_ID_RETIRO AND ESTADO IN('BORRADOR','EN_PROCESO') LIMIT 1;
    IF V_ID_EMPLEADO IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El proceso no existe o no se puede finalizar.'; END IF;
    SELECT COUNT(*) INTO V_PENDIENTES FROM bbf_retiro_actividades A JOIN bbf_retiro_tipos_actividad T ON T.ID_TIPO_ACTIVIDAD_RETIRO=A.ID_TIPO_ACTIVIDAD_RETIRO WHERE A.ID_RETIRO=P_ID_RETIRO AND T.OBLIGATORIA=1 AND A.ESTADO NOT IN('COMPLETADA','NO_APLICA');
    IF V_PENDIENTES>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='No se puede finalizar: existen actividades obligatorias pendientes.'; END IF;
    SELECT COUNT(*) INTO V_DOCS_INCOMPLETOS
    FROM bbf_retiro_actividades A JOIN bbf_retiro_tipos_actividad T ON T.ID_TIPO_ACTIVIDAD_RETIRO=A.ID_TIPO_ACTIVIDAD_RETIRO
    WHERE A.ID_RETIRO=P_ID_RETIRO AND T.OBLIGATORIA=1 AND T.REQUIERE_DOCUMENTO=1 AND A.ESTADO<>'NO_APLICA'
      AND (SELECT CASE WHEN T.CODIGO='PLANILLAS_SEGURIDAD_SOCIAL' THEN COUNT(DISTINCT D.PERIODO_DOCUMENTO) ELSE COUNT(*) END
           FROM bbf_empleado_documentos D JOIN bbf_tipos_documento_laboral TD ON TD.ID_TIPO_DOCUMENTO_LABORAL=D.ID_TIPO_DOCUMENTO_LABORAL
           WHERE D.ID_RETIRO=P_ID_RETIRO AND D.ELIMINADO=0 AND TD.NOMBRE=T.NOMBRE_TIPO_DOCUMENTO
             AND (T.CODIGO<>'PLANILLAS_SEGURIDAD_SOCIAL' OR D.PERIODO_DOCUMENTO REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])$')) < T.CANTIDAD_DOCUMENTOS;
    IF V_DOCS_INCOMPLETOS>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='No se puede finalizar: faltan documentos obligatorios del retiro.'; END IF;
    START TRANSACTION;
    IF V_ID_CONTRATO IS NOT NULL THEN UPDATE bbf_empleado_contratos SET ESTADO_CONTRATO='FINALIZADO',FECHA_FIN=V_FECHA_RETIRO,UPDATED_AT=CURRENT_TIMESTAMP WHERE ID_EMPLEADO_CONTRATO=V_ID_CONTRATO AND ELIMINADO=0; END IF;
    UPDATE bbf_empleados SET ESTADO_EMPLEADO='RETIRADO',FECHA_RETIRO=V_FECHA_RETIRO,UPDATED_AT=CURRENT_TIMESTAMP WHERE ID_EMPLEADO=V_ID_EMPLEADO AND ELIMINADO=0;
    UPDATE bbf_retiros_empleado SET ESTADO='COMPLETADO',ID_FINALIZADO_POR=P_ID_USUARIO,FECHA_FINALIZACION=CURRENT_TIMESTAMP,OBSERVACIONES=COALESCE(NULLIF(TRIM(P_OBSERVACIONES),''),OBSERVACIONES),UPDATED_AT=CURRENT_TIMESTAMP WHERE ID_RETIRO=P_ID_RETIRO;
    COMMIT;
    SELECT ID_RETIRO,ID_EMPLEADO,ESTADO,FECHA_RETIRO,FECHA_FINALIZACION FROM bbf_retiros_empleado WHERE ID_RETIRO=P_ID_RETIRO;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_RETIROS_LISTAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_RETIROS_LISTAR`(IN P_ID_EMPLEADO INT, IN P_ESTADO VARCHAR(20), IN P_FECHA_DESDE DATE, IN P_FECHA_HASTA DATE)
BEGIN
    SELECT R.ID_RETIRO,R.ID_EMPLEADO,E.NUMERO_DOCUMENTO,CONCAT_WS(' ',E.NOMBRES,E.APELLIDOS) EMPLEADO,
           R.ID_EMPLEADO_CONTRATO,R.ID_MOTIVO_RETIRO,M.CODIGO CODIGO_MOTIVO,M.NOMBRE MOTIVO_RETIRO,
           R.FECHA_INICIO_PROCESO,R.FECHA_RETIRO,R.DETALLE_MOTIVO,R.ESTADO,R.OBSERVACIONES,
           SUM(CASE WHEN A.ESTADO='PENDIENTE' THEN 1 ELSE 0 END) ACTIVIDADES_PENDIENTES,
           R.CREATED_AT,R.UPDATED_AT
    FROM bbf_retiros_empleado R JOIN bbf_empleados E ON E.ID_EMPLEADO=R.ID_EMPLEADO
    JOIN bbf_motivos_retiro M ON M.ID_MOTIVO_RETIRO=R.ID_MOTIVO_RETIRO
    LEFT JOIN bbf_retiro_actividades A ON A.ID_RETIRO=R.ID_RETIRO
    WHERE (P_ID_EMPLEADO IS NULL OR P_ID_EMPLEADO=0 OR R.ID_EMPLEADO=P_ID_EMPLEADO)
      AND (NULLIF(TRIM(P_ESTADO),'') IS NULL OR R.ESTADO=UPPER(TRIM(P_ESTADO)))
      AND (P_FECHA_DESDE IS NULL OR R.FECHA_RETIRO>=P_FECHA_DESDE)
      AND (P_FECHA_HASTA IS NULL OR R.FECHA_RETIRO<=P_FECHA_HASTA)
    GROUP BY R.ID_RETIRO
    ORDER BY R.FECHA_RETIRO DESC,R.ID_RETIRO DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
