/*!50003 DROP PROCEDURE IF EXISTS `SP_BBF_RETIROS_OBTENER` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SP_BBF_RETIROS_OBTENER`(IN P_ID_RETIRO INT)
BEGIN
    SELECT R.*,M.CODIGO CODIGO_MOTIVO,M.NOMBRE MOTIVO_RETIRO,M.REQUIERE_RENUNCIA,
           E.NUMERO_DOCUMENTO,CONCAT_WS(' ',E.NOMBRES,E.APELLIDOS) EMPLEADO,E.CORREO,E.TELEFONO,
           C.NUMERO_CONTRATO,C.FECHA_INICIO FECHA_INICIO_CONTRATO,C.FECHA_FIN FECHA_FIN_CONTRATO,C.ESTADO_CONTRATO
    FROM bbf_retiros_empleado R JOIN bbf_motivos_retiro M ON M.ID_MOTIVO_RETIRO=R.ID_MOTIVO_RETIRO
    JOIN bbf_empleados E ON E.ID_EMPLEADO=R.ID_EMPLEADO
    LEFT JOIN bbf_empleado_contratos C ON C.ID_EMPLEADO_CONTRATO=R.ID_EMPLEADO_CONTRATO
    WHERE R.ID_RETIRO=P_ID_RETIRO;

    SELECT A.ID_RETIRO_ACTIVIDAD,T.ID_TIPO_ACTIVIDAD_RETIRO,T.CODIGO,T.NOMBRE,T.DESCRIPCION,T.OBLIGATORIA,T.REQUIERE_DOCUMENTO,T.CANTIDAD_DOCUMENTOS,T.NOMBRE_TIPO_DOCUMENTO,
           A.ESTADO,A.FECHA_CUMPLIMIENTO,A.OBSERVACIONES,A.ID_RESPONSABLE
    FROM bbf_retiro_actividades A JOIN bbf_retiro_tipos_actividad T ON T.ID_TIPO_ACTIVIDAD_RETIRO=A.ID_TIPO_ACTIVIDAD_RETIRO
    WHERE A.ID_RETIRO=P_ID_RETIRO ORDER BY T.ORDEN,T.NOMBRE;

    SELECT D.*,TD.NOMBRE TIPO_DOCUMENTO
    FROM bbf_empleado_documentos D JOIN bbf_tipos_documento_laboral TD ON TD.ID_TIPO_DOCUMENTO_LABORAL=D.ID_TIPO_DOCUMENTO_LABORAL
    WHERE D.ID_RETIRO=P_ID_RETIRO AND D.ELIMINADO=0 ORDER BY D.FECHA_CARGA DESC;

    SELECT * FROM bbf_retiro_entrevistas WHERE ID_RETIRO=P_ID_RETIRO;
END ;;
DELIMITER ;
