CREATE  PROCEDURE `SP_BBF_ROLES_CAMBIAR_ESTADO`(
    IN P_ID_ROL INT,
    IN P_ACTIVO TINYINT
)
BEGIN
    UPDATE bbf_roles
    SET 
        ACTIVO = P_ACTIVO,
        ELIMINADO = 0,
        FECHA_ELIMINACION = NULL,
        UPDATED_AT = CURRENT_TIMESTAMP
    WHERE ID_ROL = P_ID_ROL
      AND ELIMINADO = 0;

    SELECT ROW_COUNT() AS FILAS_AFECTADAS;
END ;;
DELIMITER ;
