CREATE  PROCEDURE `SP_BBF_ROLES_CREAR`(
    IN P_NOMBRE VARCHAR(100),
    IN P_DESCRIPCION TEXT
)
BEGIN
    INSERT INTO bbf_roles (
        NOMBRE,
        DESCRIPCION,
        ACTIVO
    )
    VALUES (
        P_NOMBRE,
        P_DESCRIPCION,
        1
    );

    SELECT LAST_INSERT_ID() AS ID_ROL;
END ;;
