)
BEGIN
    UPDATE bbf_roles
    SET
        ACTIVO = 0,
        ELIMINADO = 1,
        FECHA_ELIMINACION = CURRENT_TIMESTAMP,
        UPDATED_AT = CURRENT_TIMESTAMP
    WHERE ID_ROL = P_ID_ROL
      AND ELIMINADO = 0;

    SELECT ROW_COUNT() AS FILAS_AFECTADAS;
