CREATE  PROCEDURE `SP_BBF_ROL_OBTENER_PERMISOS`(
    IN P_ID_ROL INT
)
BEGIN
    SELECT
        P.ID_PERMISO,
        P.CODIGO,
        P.NOMBRE,
        P.DESCRIPCION,
        P.MODULO,
        P.ACTIVO
    FROM bbf_rol_permisos RP
    INNER JOIN bbf_permisos P ON P.ID_PERMISO = RP.ID_PERMISO
    WHERE RP.ID_ROL = P_ID_ROL
    ORDER BY P.MODULO ASC, P.CODIGO ASC;
END ;;
