CREATE  PROCEDURE `SP_BBF_USUARIOS_OBTENER_POR_ID`(
    IN P_ID_USUARIO INT
)
BEGIN
    SELECT
        U.ID_USUARIO,
        U.ID_EMPLEADO,
        U.NOMBRE_USUARIO,
        U.CORREO,
        U.TIPO_USUARIO,
        U.TIPO_AUTENTICACION,
        U.REQUIERE_CAMBIO_PASSWORD,
        U.CORREO_VERIFICADO,
        U.ESTADO,
        U.INTENTOS_FALLIDOS,
        U.FECHA_BLOQUEO,
        U.ULTIMO_LOGIN,
        U.CREATED_AT,
        U.UPDATED_AT,
        E.NOMBRES,
        E.APELLIDOS,
        CONCAT(E.NOMBRES, ' ', E.APELLIDOS) AS NOMBRE_COMPLETO
    FROM bbf_usuarios U
    LEFT JOIN bbf_empleados E ON E.ID_EMPLEADO = U.ID_EMPLEADO
    WHERE U.ID_USUARIO = P_ID_USUARIO;
END ;;
DELIMITER ;
