CREATE  PROCEDURE `SP_BBF_USUARIO_OBTENER_ROLES`(
    IN P_ID_USUARIO INT
)
BEGIN
    SELECT
        R.ID_ROL,
        R.NOMBRE,
        R.DESCRIPCION,
        R.ACTIVO
    FROM bbf_usuario_roles UR
    INNER JOIN bbf_roles R ON R.ID_ROL = UR.ID_ROL
    WHERE UR.ID_USUARIO = P_ID_USUARIO
      AND R.ACTIVO = 1
    ORDER BY R.NOMBRE ASC;
END ;;
