CREATE  PROCEDURE `SP_BBF_USUARIO_ROLES_ASIGNAR`(
    IN P_ID_USUARIO INT,
    IN P_ID_ROL INT
)
BEGIN
    INSERT IGNORE INTO bbf_usuario_roles (
        ID_USUARIO,
        ID_ROL
    )
    VALUES (
        P_ID_USUARIO,
        P_ID_ROL
    );

    SELECT ROW_COUNT() AS FILAS_AFECTADAS;
END ;;
