CREATE  PROCEDURE `SP_BBF_USUARIO_SESIONES_REVOCAR`(
    IN P_ID_SESION BIGINT
)
BEGIN
    UPDATE bbf_usuario_sesiones
    SET
        ACTIVO = 0,
        FECHA_REVOCACION = CURRENT_TIMESTAMP
    WHERE ID_SESION = P_ID_SESION
      AND ACTIVO = 1;

    SELECT ROW_COUNT() AS FILAS_AFECTADAS;
END ;;
